var e=JSON.parse(`{"big-toe":{"name":"Postura del dedo gordo","goodFor":"Estiramiento de isquiotibiales con conexión activa mano-pie.","instructions":"Párate con los pies juntos. Doble hacia adelante y enrolle los dedos gordos del pie con los dos primeros dedos de cada mano (o sujete una correa alrededor de los pies). Suaviza las rodillas para que la columna se pueda alargar. Al inhalar, levante el pecho hasta la mitad; al exhalar, pliegue más profundamente. Mantenga el cuello suave y el peso ligeramente hacia adelante en las puntas de los pies. Para salir, suelte los dedos de los pies, doble las rodillas y gire o levántese."},"gorilla":{"name":"Postura del gorila","goodFor":"Estiramiento profundo de los isquiotibiales y extensión de la muñeca.","instructions":"Desde un pliegue hacia adelante, deslice las manos debajo de los pies con las palmas hacia arriba y los dedos de los pies contra las muñecas. Suaviza las rodillas; deja que los codos se doblen. Alargue la columna al inhalar y dóblela al exhalar. La mandíbula y el cuello se relajan. Para salir, deslice las manos hacia afuera, doble las rodillas y levántese con cuidado."},"bird-of-paradise":{"name":"Ave del paraíso","goodFor":"Equilibrio de cadera abierta con sujeción en los hombros.","instructions":"Desde una atadura en un pliegue hacia adelante o en un ángulo lateral extendido, levántese con cuidado sobre la pierna de apoyo y extienda la pierna atada hacia un lado. Rodilla de pie blanda; pecho abierto. Mira fijamente. Mantenga la respiración suave; retroceda si el hombro o el tendón de la corva se queja. Para salir, vuelva a doblar la rodilla levantada y suelte la atadura de forma segura antes de ponerse de pie."},"revolved-bird-of-paradise":{"name":"Postura del pájaro del paraíso girado","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del pájaro del paraíso giratorio.","instructions":"Desde una atadura girada (a menudo desde una estocada o pliegue torcido), levántese sobre el pie de apoyo y extienda la pierna atada mientras mantiene la torsión. Suaviza la rodilla de apoyo. Alargar la columna; la mirada puede seguir el giro. Para salir, doble la rodilla levantada, bájela con control y suelte la atadura."},"upward-salute":{"name":"Saludo hacia arriba","goodFor":"Longitud a través del cuerpo lateral; comienzo energizante.","instructions":"Desde la montaña, inhala y extiende ambos brazos hacia afuera y hacia arriba junto a las orejas. Mantenga las costillas suaves y el cuello largo; Mire ligeramente hacia arriba sólo si se siente cómodo. Aterrice a través de los pies a medida que llegan las yemas de los dedos. Los hombros se mantienen alejados de las orejas. Exhala para bajar los brazos o dóblate hacia adelante para abandonar la postura.","breathCue":"Inhala para alcanzar hacia arriba; Mantenga los hombros suaves.","modifications":["Manos al corazón si los hombros están irritados."],"alignmentCues":["Bíceps al lado de las orejas","coxis pesado"]},"chair":{"name":"Postura de la silla","goodFor":"Fuerza de las piernas, estabilidad del tobillo y generación de calor.","instructions":"Párate con los pies juntos o a la altura de las caderas. Doble las rodillas y siente las caderas hacia atrás como si estuviera en una silla, manteniendo el peso en los talones. Levante los brazos al lado de las orejas o mantenga las manos en el corazón. Elevaciones de pecho; La espalda baja permanece larga. Las rodillas se desplazan sobre el segundo y tercer dedo del pie. Respira constantemente. Para salir, presione los pies y estire las piernas, o inclínese hacia adelante.","breathCue":"Respiración constante en el vientre y las costillas.","modifications":["Curva menos profunda","Pies a la altura de las caderas"],"deepen":["Siéntate más abajo sólo mientras las rodillas siguen a los dedos de los pies."],"commonMistakes":["Rodillas más allá de los dedos de los pies sin control.","Colapso del pecho"]},"high-lunge":{"name":"estocada alta","goodFor":"Fuerza de piernas, estiramiento de flexores de cadera y equilibrio.","instructions":"Da un paso hacia adelante en una postura larga; El talón trasero se levanta, la pierna trasera está fuerte. La rodilla delantera se dobla sobre el tobillo. Caderas cuadradas hacia adelante; Los brazos se extienden hacia arriba o se quedan en el corazón. Suaviza los hombros. Para salir, baje las manos y dé un paso con el pie trasero hacia adelante, o doble la pierna delantera.","breathCue":"Inhalar elevación; exhale la raíz a través de los pies.","modifications":["Acortar la postura","manos al corazon"],"commonMistakes":["Rodilla delantera colapsando hacia adentro"]},"low-lunge":{"name":"estocada baja","goodFor":"Apertura profunda de los flexores de la cadera y preparación suave de la flexión hacia atrás.","instructions":"Desde Down Dog o de pie, da un paso hacia adelante entre las manos. Baje la rodilla trasera si se siente cómodo; Saque los dedos de atrás. La rodilla delantera se coloca sobre el tobillo. Manos en la parte delantera del muslo, bloques o estiradas hacia arriba. Cuadre las caderas hacia adelante suavemente. Para salir, plante las manos y retroceda hasta Down Dog o retírese.","breathCue":"Exhale para mover las caderas hacia adelante suavemente.","modifications":["Manos en la parte delantera del muslo"],"deepen":["Levante los brazos cuando esté estable."],"avoidIf":["Se necesita amortiguación para las rodillas: siempre almohadilla"],"props":["manta debajo de la rodilla trasera"]},"eagle":{"name":"Postura del águila","goodFor":"Equilibrio, estiramiento de hombros y compromiso externo de la cadera.","instructions":"Doble ligeramente ambas rodillas. Envuelva un muslo sobre el otro y enganche el pie detrás de la pantorrilla si está disponible. Cruza los brazos opuestos a las piernas: un codo debajo del otro, con las palmas una hacia la otra o tocándose. Sienta las caderas hacia atrás; levantar los codos. Mirada suave. Para salir, desenvuelva las extremidades lentamente y manténgase erguido.","breathCue":"Respiración constante por la nariz.","modifications":["Cruzar una vez sin envolver","Siéntate en una silla"]},"standing-foot-behind-the-head":{"name":"Postura del pie detrás de la cabeza","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del pie detrás de la cabeza.","instructions":"Estando de pie, coloque con cuidado un pie detrás de la cabeza o sobre los hombros solo si la movilidad lo permite; use una pared y nunca fuerce la rodilla. Suaviza la pierna de apoyo. Para salir, suelta el pie lentamente con ambas manos apoyándote."},"standing-foot-to-head":{"name":"Postura de pie a cabeza","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de pie con la cabeza.","instructions":"Párese sobre un pie y acerque el otro pie hacia la cabeza con las manos o con una correa. Suaviza la rodilla de apoyo; pelvis estable. Para salir, baje el pie con control."},"standing-foot-behind-the-head-forward-bend":{"name":"Pie de pie detrás de la cabeza Postura de flexión hacia adelante","goodFor":"Desarrolla movilidad, fuerza y ​​​​conciencia para la postura de pie inclinado detrás de la cabeza hacia adelante.","instructions":"Desde la posición de pie con los pies detrás de la cabeza, gire hacia adelante con cuidado con apoyo. Suaviza la rodilla de apoyo. Mantenga la respiración suave. Para salir, levante el torso y suelte el pie atado."},"half-standing-forward-bend":{"name":"Postura de media flexión hacia adelante de pie","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de media flexión hacia adelante.","instructions":"Desde un pliegue hacia adelante, coloque las yemas de los dedos o las manos sobre las espinillas o los bloques. Inhale y levante el pecho hasta la mitad para que la columna quede larga y aproximadamente paralela al suelo. Mira suavemente hacia el suelo; cuello en línea con la columna. Mantenga una flexión suave de las rodillas si los isquiotibiales están tensos. Exhala para doblarte nuevamente o da un paso atrás para salir.","breathCue":"Inhale para levantar una columna larga; mirada suave.","modifications":["Manos en los muslos en lugar de espinillas."],"alignmentCues":["Yemas de los dedos debajo de los hombros","Alargar la corona hacia adelante"]},"standing-forward-bend":{"name":"Postura de flexión hacia adelante de pie","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de flexión de pie hacia adelante.","instructions":"De pie, gire las caderas y doble el torso sobre las piernas. Suaviza las rodillas tanto como sea necesario para que la columna se alargue. Deja que la cabeza cuelgue; Sujete los codos, las espinillas o el suelo. Cambie el peso ligeramente hacia las puntas de los pies. Respire hacia la espalda del cuerpo. Para salir, doble las rodillas, enganche el vientre y gire o levántese con la columna larga.","breathCue":"Exhala para doblar; Inhale para alargar ligeramente la columna.","modifications":["Doble las rodillas generosamente","Manos a las espinillas"],"deepen":["Estire las piernas sólo si la columna se mantiene larga."],"avoidIf":["Inflamación aguda del disco lumbar (mantenga las rodillas dobladas)"],"commonMistakes":["Redondeando con fuerza desde la espalda baja","rodillas bloqueadas"],"alignmentCues":["Bisagra desde las caderas","Deja que la cabeza cuelgue pesada"],"props":["bloquear bajo las manos"]},"standing-half-bound-lotus-forward-bend":{"name":"Postura de loto de pie, medio atado, inclinado hacia adelante","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de flexión hacia adelante del loto medio atado de pie.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura de flexión hacia adelante del loto medio atado de pie, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"goddess":{"name":"Postura de la diosa","goodFor":"Fuerza interna del muslo, apertura de cadera y calor.","instructions":"Adopte una postura amplia con los dedos de los pies girados aproximadamente a 45°. Doble las rodillas sobre los dedos de los pies y siéntese con las caderas hacia abajo. Los brazos pueden llegar a la altura de los hombros o llegar por encima de la cabeza. Mantenga la columna larga; Evite doblar con fuerza. Las rodillas van en línea con los dedos de los pies. Para salir, estire las piernas y gire los dedos de los pies hacia adelante.","breathCue":"Inhala levanta el corazón; exhale, doble las rodillas."},"half-moon":{"name":"Medialuna","goodFor":"Equilibrio, fuerza de la cadera y apertura lateral.","instructions":"Desde Triángulo o una postura corta, coloque la mano delantera sobre un bloque o el suelo delante del pie de apoyo. Levante la pierna trasera paralela al suelo y abra la parte superior de la cadera y el brazo hacia el cielo. Pierna de apoyo fuerte; rodilla blanda. Mirar hacia abajo, hacia adelante o hacia arriba. Para salir, baje el pie levantado y regrese al Triángulo o de pie.","breathCue":"Inhala, expande; exhale y estabilice la pierna de apoyo.","modifications":["Mantenga los dedos de los pies levantados hacia abajo","Mano más alta en el bloque"],"props":["bloque debajo de la mano inferior","muro"]},"revolved-half-moon":{"name":"Media Luna Girada","goodFor":"Equilibra con un toque desintoxicante.","instructions":"Desde un pliegue corto o Triángulo Girado, planta la mano opuesta y levanta la pierna trasera. Gire el cofre para abrirlo hacia el lado de la pierna de apoyo; el brazo superior se eleva. Las caderas se apilan tanto como lo permita el equilibrio. Mirada suave. Para salir, baje el pie levantado y desenrosque con cuidado."},"extended-standing-hand-to-big-toe":{"name":"Postura de la mano extendida al dedo gordo del pie","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura extendida de la mano de pie al dedo gordo.","instructions":"Mantente erguido. Sostenga un dedo gordo del pie o una correa y extienda esa pierna hacia adelante, luego ábrala hacia un lado según lo permita la movilidad. Suaviza la rodilla de apoyo; nivel de la pelvis. Para salir, regrese la pierna al centro y suéltela."},"revolved-standing-hand-to-big-toe":{"name":"Postura de la mano de pie girada hasta el dedo gordo del pie","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de la mano de pie girada hasta el dedo gordo.","instructions":"Sujete un pie con la mano opuesta o con una correa y gírelo suavemente mientras la pierna se extiende. Suaviza la rodilla de apoyo. Alarga la columna antes de profundizar. Para salir, desenrosque, doble la rodilla y suelte."},"standing-hand-to-big-toe":{"name":"Postura de la mano de pie al dedo gordo del pie","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de la mano de pie al dedo gordo.","instructions":"Comience de pie con pies firmes y una mirada suave. Organice el cuerpo en la postura de la mano de pie al dedo gordo: coloque los pies primero, luego las manos o los brazos, luego alargue la columna. Suaviza cualquier articulación que se sienta comprimida; mantén la respiración tranquila. Sostenga a una profundidad que pueda sostener sin agarrar la mandíbula. Para salir, invertir la entrada con control y volver a montaña o hacer un pliegue hacia adelante antes de continuar."},"mountain":{"name":"Postura de montaña","goodFor":"Postura, conexión a tierra y conciencia corporal.","instructions":"Párese con los pies paralelos, a la altura de las caderas o juntos, con el peso uniforme en ambos pies. Suaviza ligeramente las rodillas y alarga la columna como si una cuerda levantara la coronilla. Gire los hombros hacia atrás y hacia abajo; Los brazos descansan a los lados con las palmas abiertas. Mirada suave y hacia adelante. Respire constantemente por la nariz. Para salir, simplemente adopta la siguiente forma o dobla las rodillas y dóblate.","breathCue":"Respire constantemente; alargar al inhalar.","modifications":["Pies a la altura de las caderas si el equilibrio se siente inestable"],"deepen":["Cierra los ojos durante 3 respiraciones."],"commonMistakes":["Bloquear las rodillas","Costillas empujando hacia adelante"],"alignmentCues":["Arraiga las cuatro esquinas de los pies.","Suaviza las rodillas y levanta la coronilla."]},"pyramid":{"name":"Postura de la pirámide","goodFor":"Estiramiento intenso de los isquiotibiales con cuadratura de cadera.","instructions":"Desde una posición de estocada corta, ambos pies miran hacia adelante y las piernas se estiran (las rodillas suaves están bien). Bisagra en las caderas y doblar sobre la pierna delantera. Las manos enmarcan el pie delantero o descansan sobre bloques. Cuadre las caderas hacia el frente. Alargue la columna al inhalar; Profundice el pliegue al exhalar. Para salir, levante el pecho hasta la mitad y junte los pies."},"extended-side-angle":{"name":"Ángulo lateral extendido","goodFor":"Apertura profunda de cadera y costado del cuerpo con fuerza en las piernas.","instructions":"Desde Warrior II, inclina el torso sobre la pierna delantera doblada. Apoye el antebrazo delantero sobre el muslo o la mano sobre un bloque o el suelo dentro del pie delantero. El brazo superior llega hasta la oreja o hacia arriba. Alarga ambos lados de la cintura. Mire hacia arriba, hacia adelante o hacia abajo. Para salir, presione los pies y vuelva a subir al Guerrero II.","breathCue":"Inhala y abre las costillas superiores; exhale y apoye los pies.","modifications":["Antebrazo en la parte delantera del muslo"],"props":["bloque debajo de la mano inferior"]},"standing-splits":{"name":"Postura de división de pie","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de división de pie.","instructions":"Desde un pliegue hacia adelante sobre una pierna, transfiera el peso al pie de apoyo y levante la otra pierna detrás de usted. Las manos enmarcan el pie de apoyo o sujetan el tobillo. Suaviza la rodilla de apoyo; las caderas permanecen relativamente cuadradas. Para salir, baje la pierna levantada y vuelva a doblarse o ponerse de pie."},"dancer":{"name":"Pose de bailarina","goodFor":"Equilibrio, estiramiento de la parte delantera del cuerpo y concentración.","instructions":"Párese sobre un pie, sostenga el pie opuesto detrás de usted e inclínese hacia adelante mientras patea el pie hacia arriba y hacia atrás. Lleve el brazo libre hacia adelante. Suaviza la rodilla de apoyo. Para salir, vuelva a ponerse erguido y suelte el pie."},"tree":{"name":"Postura del árbol","goodFor":"Equilibrio, concentración y apertura de cadera sobre la pierna levantada.","instructions":"Párate sobre un pie. Coloque la planta del otro pie en la parte interna de la pantorrilla o del muslo, nunca en la rodilla. La cadera de la pierna doblada se abre suavemente. Manos en el corazón o estiradas hacia arriba. Mirada suave sobre un punto fijo. Alarga la columna. Para salir, baje el pie con el control y cambie cuando esté listo.","breathCue":"Respiración suave y constante; suavizar la mandíbula.","modifications":["Dedos en el suelo","Pie hasta tobillo (no rodilla)"],"deepen":["Mirar hacia arriba cuando esté estable"],"commonMistakes":["Pie presionando la articulación de la rodilla."],"props":["pared cercana"]},"triangle":{"name":"Postura del triángulo","goodFor":"Longitud lateral del cuerpo, estiramiento de los isquiotibiales y movilidad de la columna.","instructions":"Desde una postura amplia, estire la pierna delantera e incline el torso sobre ella. La mano delantera descansa sobre la espinilla, el tobillo, el bloque o el suelo; el brazo superior llega hacia el cielo. Mantenga ambos lados de la cintura largos; Evite colapsar sobre la cadera delantera. Suaviza ligeramente las rodillas si es necesario. Mire hacia arriba, hacia adelante o hacia abajo. Para salir, active el núcleo y levántese con una columna larga.","breathCue":"Inhalar alargar; exhale la bisagra sin colapsar.","modifications":["Mano más arriba en la espinilla","Postura más corta"],"deepen":["El brazo superior se acumula solo cuando el cofre está abierto"],"commonMistakes":["Redondeando hacia adelante","Rodilla delantera hiperextendida"],"props":["bloque debajo de la mano inferior"]},"revolved-triangle":{"name":"Triángulo girado","goodFor":"Soporte de digestión giratorio con estiramiento de isquiotibiales.","instructions":"Desde la postura de pirámide, coloque una mano fuera o dentro del pie delantero (use un bloque). Inhala para alargar; exhale para girar el torso hacia la pierna delantera, con el brazo superior hacia arriba. Mantenga las caderas relativamente niveladas. Rodillas suaves. Mirar hacia arriba o hacia abajo. Para salir, desenrosque y levante el torso, luego junte los pies.","breathCue":"Exhala para girar; Nunca contengas la respiración.","modifications":["mano a la espinilla","rodilla delantera doblada"],"avoidIf":["Embarazo tardío","Problemas agudos de disco: mantenga las torceduras leves"],"commonMistakes":["Forzando el giro desde el cuello."],"props":["bloque debajo de la mano inferior"]},"warrior-i":{"name":"Guerrero yo poso","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Warrior I Pose.","instructions":"Desde una estocada o Down Dog, avanza un pie entre las manos y levántate. La rodilla delantera se dobla sobre el tobillo; pierna trasera recta con el talón inclinado hacia adentro. Cuadre las caderas hacia adelante tanto como le resulte cómodo. Levante los brazos; hombros suaves. Mirar hacia adelante. Respira constantemente. Para salir, baje las manos y dé un paso atrás, o estire la pierna delantera.","breathCue":"Inhale, levante el cofre; Exhale la raíz del talón trasero.","modifications":["Manos a las caderas","Acortar la postura"],"commonMistakes":["Colapso de rodilla delantera","lumbar general"],"alignmentCues":["Rodilla delantera sobre el tobillo.","Pie trasero en ángulo ~45°"]},"warrior-ii":{"name":"Postura del guerrero II","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la Pose del Guerrero II.","instructions":"Adopte una postura amplia con los pies separados aproximadamente a la altura de una pierna. Gire los dedos delanteros 90° hacia afuera y el pie trasero ligeramente hacia adentro. Bend the front knee over the ankle; arms reach to the sides at shoulder height. Gaze over the front hand. Hips open to the side wall. Suaviza los hombros. Para salir, estire la pierna delantera y baje los brazos, o haga una voltereta con las manos hacia abajo.","breathCue":"Respire hacia el costado del cuerpo; mirada suave sobre los dedos delanteros.","modifications":["manos en las caderas","Acortar la postura"],"deepen":["Doble la rodilla delantera más profundamente cuando el muslo esté estable."],"alignmentCues":["Hombros sobre las caderas","La rodilla delantera sigue el segundo dedo del pie."]},"warrior-iii":{"name":"Postura del guerrero III","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del Guerrero III.","instructions":"De pie o Guerrero I, transfiera el peso a un pie e incline el torso hacia adelante mientras la otra pierna se levanta detrás de usted. Apunte a una forma de T: el torso y la pierna levantada aproximadamente paralelos al suelo. Los brazos se extienden hacia adelante, hacia atrás o hacia el corazón. Cuadre las caderas hacia el suelo. Mirada suave. Para salir, baje el pie levantado con control.","breathCue":"Respiración constante; no lo sostengas para mantener el equilibrio.","modifications":["Manos a los bloques","Mantenga los dedos de los pies levantados en el suelo."],"avoidIf":["Esguince agudo de tobillo en la pierna de apoyo"],"commonMistakes":["Caderas apiladas abiertas","Bloqueo de rodilla de pie"],"props":["pared para los dedos de los pies o las manos"]},"wide-legged-forward-bend-i":{"name":"Postura con curvatura hacia adelante con las piernas anchas","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura I con flexión hacia adelante con piernas anchas.","instructions":"Párese con una postura amplia, con los dedos de los pies ligeramente hacia adentro. Gire las caderas y dóblese hacia adelante; manos al suelo, bloques o un lazo. Mantenga el peso uniforme en ambos pies. Suaviza las rodillas si los isquiotibiales están tensos. Para salir, involucra el vientre y levántate con una columna larga, luego introduce los pies."},"wide-legged-forward-bend-ii":{"name":"Postura de flexión hacia adelante II con las piernas anchas","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de flexión II con piernas anchas hacia adelante.","instructions":"Comience de pie con pies firmes y una mirada suave. Coloque el cuerpo en la postura de flexión II con las piernas anchas hacia adelante: coloque los pies primero, luego las manos o los brazos, luego alargue la columna. Suaviza cualquier articulación que se sienta comprimida; mantén la respiración tranquila. Sostenga a una profundidad que pueda sostener sin agarrar la mandíbula. Para salir, invertir la entrada con control y volver a montaña o hacer un pliegue hacia adelante antes de continuar."},"wide-legged-forward-bend-iii":{"name":"Postura de flexión hacia adelante III con las piernas anchas","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de flexión hacia adelante con piernas anchas III.","instructions":"Comience de pie con pies firmes y una mirada suave. Coloque el cuerpo en la postura III de flexión hacia adelante con las piernas anchas: coloque los pies primero, luego las manos o los brazos, luego alargue la columna. Suaviza cualquier articulación que se sienta comprimida; mantén la respiración tranquila. Sostenga a una profundidad que pueda sostener sin agarrar la mandíbula. Para salir, invertir la entrada con control y volver a montaña o hacer un pliegue hacia adelante antes de continuar."},"wide-legged-forward-bend-iv":{"name":"Postura IV con curvatura hacia adelante y piernas anchas","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura IV con piernas anchas hacia adelante.","instructions":"Adopte una postura amplia y dóblese; Junte las manos detrás de la espalda y dóblelas más profundamente, o use la unión tradicional para esta variación. Suaviza las rodillas. Mantenga el peso uniforme en ambos pies. Para salir, suelte las manos, levante el pecho y meta los pies."},"revolved-wide-legged-forward-bend":{"name":"Inclinación hacia adelante con las piernas anchas y giradas","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la flexión hacia adelante con las piernas anchas y giradas.","instructions":"Desde un pliegue con las piernas abiertas, lleve una mano al pie opuesto y abra el otro brazo hacia el cielo, girando el torso. Suaviza las rodillas. Mirar hacia arriba o hacia abajo. Para salir, suelte hasta un pliegue neutral y luego levántese."},"side-wide-legged-forward-bend":{"name":"Inclinación hacia adelante con las piernas anchas de lado","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la flexión lateral con las piernas anchas hacia adelante.","instructions":"Comience de pie con pies firmes y una mirada suave. Coloque el cuerpo en una flexión hacia adelante con las piernas anchas hacia los lados: coloque los pies primero, luego las manos o los brazos, luego alargue la columna. Suaviza cualquier articulación que se sienta comprimida; mantén la respiración tranquila. Sostenga a una profundidad que pueda sostener sin agarrar la mandíbula. Para salir, invertir la entrada con control y volver a montaña o hacer un pliegue hacia adelante antes de continuar."},"archers":{"name":"Arquero\\\\","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Archer\\\\","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para Archer\\\\, luego alargue la columna mientras inhala antes de doblar, torcer o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"boat":{"name":"Postura del barco","goodFor":"Fuerza central profunda y equilibrio.","instructions":"Siéntate con las rodillas dobladas y los pies en el suelo. Inclínese ligeramente hacia atrás, levante los pies y mantenga el equilibrio sobre los isquiones. Espinillas paralelas al suelo (o piernas estiradas). Los brazos se extienden hacia adelante junto a las rodillas. Lomo largo; pecho abierto. Suaviza el cuello. Para salir, baje los pies y siéntese erguido.","breathCue":"Respiración constante; no se prepare conteniendo la respiración.","modifications":["Sostenga los muslos","Pies abajo"]},"bound-angle":{"name":"Ángulo enlazado","goodFor":"Flexibilidad de cadera e ingle.","instructions":"Siéntate erguido, junta las plantas de los pies y deja que las rodillas se abran. Sostenga los pies o los tobillos. Siéntate sobre una manta si la espalda baja se redondea. Doble hacia adelante sólo si la columna se mantiene larga. Suaviza la parte interna de los muslos. Para salir, utiliza las manos para cerrar las rodillas y extender las piernas.","breathCue":"Aliento suave del vientre; sin forzar las rodillas.","modifications":["Siéntate más alto","Pies más alejados de la pelvis"],"props":["bloques debajo de las rodillas","manta debajo de los isquiones"]},"both-feet-behind-the-head-i":{"name":"Ambos pies detrás de la cabeza poso","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para ambos pies detrás de la cabeza que pose.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para Ambos pies detrás de la cabeza en la postura I, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"cow-face":{"name":"Postura de cara de vaca","goodFor":"Apertura de cadera y hombro juntos.","instructions":"Siéntate con las rodillas apiladas (una encima de la otra) o simplemente con las piernas cruzadas si las caderas están apretadas. Levante un brazo y doble el codo; el otro brazo llega detrás de la espalda: abroche o sujete una correa. Siéntate erguido. Suaviza la mandíbula. Para salir, suelte los brazos y cambie las posiciones de piernas y brazos."},"easy":{"name":"Postura fácil","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Easy Pose.","instructions":"Siéntate con las piernas cruzadas y la columna alta. Si las rodillas están altas, siéntese sobre una manta doblada. Las manos descansan sobre los muslos o en el regazo. Suaviza los hombros y la mandíbula. Respire constantemente por la nariz. Para salir, descruza las piernas lentamente y estíralas hacia adelante."},"fire-log":{"name":"Postura del tronco de fuego","goodFor":"Estiramiento profundo de la cadera exterior; Alivio de la región de banda IT.","instructions":"Siéntese con una espinilla paralela al frente de la colchoneta y apile la otra espinilla encima (el tobillo sobre la rodilla, según esté disponible). Siéntate sobre una manta si es necesario. Doble hacia adelante solo con el lomo largo. Suaviza las caderas. Para salir, desapile con cuidado las piernas y sacúdalas."},"embryo-in-womb":{"name":"Embrión en postura del útero","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia del embrión en la postura del útero.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para el embrión en la postura del útero, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"foot-behind-the-head-i":{"name":"Pie detrás de la cabeza poso","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para el pie detrás de la cabeza que pose.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura del pie detrás de la cabeza, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"foot-behind-the-head-ii":{"name":"Postura del pie detrás de la cabeza II","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del pie detrás de la cabeza II.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura del pie detrás de la cabeza II, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"seated-forward-bend-i":{"name":"Postura de flexión hacia adelante sentado","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura Sentado hacia adelante en curva I.","instructions":"Desde el bastón, inhale para alargar la columna, exhale haciendo bisagra en las caderas y doble las piernas. Sujete los pies, las espinillas o una correa. Suaviza las rodillas si la espalda baja se curva. Mantenga el cuello largo. Para salir, inhala para levantar el torso con la columna larga.","breathCue":"Inhalar alargar; exhale el pliegue desde las caderas.","modifications":["rodillas dobladas","Siéntate sobre una manta doblada"],"avoidIf":["Desgarro agudo del tendón de la corva"],"props":["correa alrededor de los pies","manta debajo de las rodillas"]},"seated-forward-bend-ii":{"name":"Postura de flexión sentada hacia adelante II","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura Seated Forward Bend II.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura de flexión sentada hacia adelante II, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"seated-forward-bend-iii":{"name":"Postura de flexión sentada hacia adelante III","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura Seated Forward Bend III.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura de flexión sentada hacia adelante III, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"seated-forward-bend-iv":{"name":"Postura IV de curvatura hacia adelante sentado","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura IV de flexión sentada hacia adelante.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura IV de flexión sentada hacia adelante, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"seated-half-bound-lotus-forward-bend":{"name":"Postura de loto sentado medio atado inclinado hacia adelante","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de flexión hacia adelante del loto medio atado sentado.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura de flexión hacia adelante del loto medio atado sentado, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"seated-three-limbed-forward-bend":{"name":"Postura de flexión hacia adelante sentado con tres extremidades","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de flexión hacia adelante con tres extremidades sentadas.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura de flexión hacia adelante sentado con tres extremidades, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"garland":{"name":"Postura de la guirnalda","goodFor":"Apertura de cadera, movilidad de tobillo y conciencia del suelo pélvico.","instructions":"De pie, con los pies a la altura de las caderas o más anchos, los dedos de los pies ligeramente hacia afuera. Doble las rodillas profundamente en cuclillas, con los talones hacia abajo si es posible (eleve los talones girando si no). Los codos presionan la parte interna de las rodillas; manos en el corazón. Lomo largo; pecho levantado. Para salir, planta las manos y estira las piernas, o siéntate en el suelo.","breathCue":"Respiración constante en cuclillas bajas.","modifications":["Siéntate en un bloque"],"props":["manta debajo de los talones"]},"seated-gate":{"name":"Postura de la puerta sentada","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de puerta sentada.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura de la puerta sentada, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"head-to-knee-i":{"name":"Poso de cabeza a rodilla","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de cabeza a rodilla.","instructions":"Siéntate con una pierna extendida y el otro pie en la parte interna del muslo. Cuadra el torso sobre la pierna extendida y dobla. Sujeta el pie o una correa. Suaviza la rodilla extendida si es necesario. Mantenga ambos isquiones firmes. Para salir, levante el torso y cambie de pierna cuando esté listo."},"head-to-knee-ii":{"name":"Postura de cabeza a rodilla II","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de cabeza a rodilla II.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura de la cabeza a las rodillas II, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"head-to-knee-iii":{"name":"Postura de cabeza a rodilla III","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de cabeza a rodilla III.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Organice las piernas para la postura de la cabeza a las rodillas III, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"hero":{"name":"Pose de héroe","goodFor":"Asiento cuádruple para estiramiento y meditación.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Organice las piernas para la postura del héroe, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"heron":{"name":"Postura de la garza","goodFor":"Estiramiento intenso de los isquiotibiales con compromiso del core.","instructions":"Siéntate erguido. Sostenga un pie con ambas manos y extienda esa pierna hacia arriba tan recta como le resulte cómodo; la otra pierna permanece doblada o extendida en el suelo. Lomo largo; hombros suaves. Para salir, doble la rodilla levantada y suelte el pie."},"noose":{"name":"Postura de la soga","goodFor":"Giro profundo con movilidad de tobillo y hombro.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura de la soga, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"half-pigeon":{"name":"media paloma","goodFor":"Variación de paloma accesible para apertura de cadera.","instructions":"Desde Down Dog o una estocada, lleve una espinilla hacia adelante a través de la colchoneta (el tobillo cerca de la muñeca opuesta, lo más cómodo posible). Extiende la pierna trasera recta hacia atrás. Cuadra las caderas; use una manta debajo de la cadera delantera si es necesario. Doble hacia adelante sobre la pierna delantera o manténgase erguido. Para salir, meta los dedos de atrás, levántelos y dé un paso atrás.","breathCue":"Exhalaciones largas y suaves hacia la parte exterior de la cadera.","modifications":["Figura cuatro en la espalda","Mantenga el torso erguido"],"avoidIf":["Dolor agudo en la rodilla: cambie a la figura de cuatro"],"commonMistakes":["Forzar la espinilla delantera paralela"],"props":["manta debajo de la cadera"]},"lotus":{"name":"Postura del loto","goodFor":"Asiento de meditación clásico; apertura profunda de la cadera.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura del loto, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"sage-marichis-i":{"name":"Marichi salvia\\\\","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Sage Marichi\\\\","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Acomode las piernas para Sage Marichi\\\\, luego alargue la columna mientras inhala antes de doblar, torcer o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"side-lunge":{"name":"estocada lateral","goodFor":"Fuerza interna del muslo y movilidad lateral de la cadera.","instructions":"Desde una postura amplia, doble una rodilla y mueva las caderas hacia ese talón mientras la otra pierna permanece extendida. Manos en el suelo, bloques o muslos. Ambos pies puestos a tierra; Los dedos de la pierna doblada apuntan aproximadamente en la misma dirección que la rodilla. Lomo largo. Para salir, presione la pierna doblada y regrese al centro, luego cambie."},"front-splits":{"name":"Aberturas frontales","goodFor":"Flexibilidad total en las divisiones de las piernas delanteras.","instructions":"Vaya al suelo y configure Front Splits con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"half-splits":{"name":"Postura de media división","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Half Splits Pose.","instructions":"Desde una estocada baja, mueva las caderas hacia atrás sobre la rodilla trasera y estire la pierna delantera tanto como le resulte cómodo. Flexiona los dedos delanteros hacia el techo. Bisagra y pliegue sobre la pata delantera; las manos enmarcan la pierna o descansan sobre bloques. Mantenga las caderas cuadradas. Para salir, doble la rodilla delantera y avance hacia la estocada."},"wide-splits":{"name":"Divisiones amplias","goodFor":"Flexibilidad de pierna ancha y apertura de ingle.","instructions":"Siéntate con las piernas bien abiertas. Gire las caderas y camine con las manos hacia adelante, manteniendo la columna larga. Flexiona los pies. Suaviza ligeramente las rodillas si los isquiotibiales protestan. Para salir, introduzca las manos y junte las piernas."},"staff":{"name":"Postura del personal","goodFor":"Bases de la postura sentada y compromiso de las piernas.","instructions":"Siéntate con ambas piernas extendidas y rectas y los pies flexionados. Siéntate erguido sobre los isquiones; alargar la columna. Las manos al lado de las caderas presionan ligeramente hacia abajo. Suaviza las costillas delanteras. Para salir, doble las rodillas o dóblese hacia adelante para adoptar la siguiente forma."},"thunderbolt":{"name":"Postura del rayo","goodFor":"Movilidad del asiento y del tobillo favorable a la digestión.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura del rayo, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"toe-stand":{"name":"Soporte para los pies","goodFor":"Fuerza del tobillo y equilibrio intenso.","instructions":"Desde una preparación en cuclillas o Half Lotus, levántese con cuidado sobre la punta del pie que está de pie con el otro pie atado, usando las manos en el suelo para mantener el equilibrio según sea necesario. Suaviza el tobillo de pie. Lomo largo. Para salir, baje las manos y la cadera con control."},"banana":{"name":"Postura del plátano","goodFor":"Estiramiento lateral del cuerpo y liberación lateral reparadora.","instructions":"Acuéstese boca arriba. Camine con ambos pies y ambos brazos hacia un lado para que el cuerpo forme una suave curva tipo banana. Suaviza el lado opuesto del cuerpo. Descanse la cabeza cómodamente. Para salir, regrese al centro y cambie la curva."},"bridge":{"name":"Postura del puente","goodFor":"Fuerza de glúteos, apertura del pecho e inversión suave.","instructions":"Acuéstese boca arriba, con las rodillas dobladas y los pies a la altura de las caderas debajo de las rodillas. Presione los pies y levante las caderas. Entrelaza las manos debajo de la espalda o mantén los brazos a los lados. Suavizar el cuello; mirar hacia arriba. Las rodillas pasan por encima de los tobillos. Para salir, suelta las manos y baja la columna vértebra a vértebra.","breathCue":"Inhalar elevación; exhale y mantenga las rodillas en dirección vertical.","modifications":["Mantenga una altura más baja"],"avoidIf":["Problemas agudos del cuello: mantenga la mirada neutral, sin girar la cabeza"],"props":["bloque entre los muslos"]},"corpse":{"name":"Postura del cadáver","goodFor":"Integración, descanso y reseteo del sistema nervioso.","instructions":"Acuéstese boca arriba con las piernas extendidas y los brazos un poco alejados del cuerpo, con las palmas hacia arriba. Suaviza los pies y déjalos caer abiertos. Cierra los ojos si te sientes cómodo. Libera la mandíbula, los hombros y el vientre. Respira naturalmente sin esfuerzo. Quédese hasta que esté listo para rodar hacia un lado y sentarse lentamente.","breathCue":"Aliento natural; no se necesita control.","modifications":["Apoyar la cabeza","Acostado de lado si es necesario"],"alignmentCues":["Palmas suaves","Los pies se abren"],"props":["manta debajo de las rodillas","almohada para los ojos"]},"fish":{"name":"Postura del pez","goodFor":"Abertura de pecho y garganta; contraponerse a los pliegues hacia adelante.","instructions":"Acuéstese boca arriba. Deslice las manos debajo de las caderas, con las palmas hacia abajo. Presione los codos y levante el pecho; La coronilla de la cabeza puede descansar ligeramente sobre la colchoneta. Piernas extendidas o rodillas flexionadas. Suaviza la garganta. Para salir, levante primero la cabeza y luego baje la columna.","breathCue":"Inhala y abre la garganta; mantenga la mandíbula suave.","modifications":["Pescado apoyado sobre un refuerzo."],"props":["bloquear debajo de los omóplatos"]},"supine-foot-to-head":{"name":"Postura supina del pie a la cabeza","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura supina del pie a la cabeza.","instructions":"Vaya al suelo y establezca la postura del pie a la cabeza en decúbito supino con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"extended-supine-hand-to-big-toe":{"name":"Postura de la mano en decúbito supino extendido al dedo gordo del pie","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura extendida de la mano en decúbito supino al dedo gordo del pie.","instructions":"Vaya al suelo y establezca la postura de la mano extendida en decúbito supino hasta el dedo gordo del pie con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"supine-hand-to-big-toe":{"name":"Postura de la mano al dedo gordo del pie en decúbito supino","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de la mano supina al dedo gordo.","instructions":"Acuéstese boca arriba. Enrolle una correa alrededor de un pie o sostenga el dedo gordo; Extienda esa pierna hacia el techo (o tan alto como le resulte cómodo). La otra pierna permanece mucho tiempo en el suelo o doblada. Suaviza los hombros. Mantenga la pelvis nivelada. Para salir, doble la rodilla levantada y suelte la correa o el dedo del pie."},"happy-baby":{"name":"bebe feliz","goodFor":"Apertura de cadera y divertido estiramiento de isquiotibiales.","instructions":"Acuéstese boca arriba. Doble las rodillas hacia el pecho y sostenga la parte exterior del pie o el dedo gordo del pie. Abra las rodillas más que el torso; suelas hacia arriba. Agítese suavemente o quédese quieto. Suaviza la espalda baja en la colchoneta. Para salir, suelta los pies y extiende las piernas.","breathCue":"Aliento libre y juguetón.","modifications":["Sostenga la parte posterior de los muslos"]},"sleeping-yogi":{"name":"Postura del yogui dormido","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del yogui dormido.","instructions":"Vaya al suelo y establezca la postura del yogui dormido con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"supine-spinal-twist":{"name":"Postura de torsión espinal en decúbito supino","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de torsión espinal supina.","instructions":"Acuéstese boca arriba con las rodillas dobladas. Deje caer ambas rodillas (o una) hacia un lado; extiende los brazos en forma de T o cactus. Suaviza el hombro opuesto hacia el suelo sin forzar. La mirada puede seguir el camino opuesto. Respire hacia las costillas. Para salir, regrese las rodillas al centro y cambie de lado.","breathCue":"Exhale con las rodillas cruzadas; Mantenga ambos hombros pesados.","modifications":["Apila una almohada debajo de las rodillas."],"props":["manta entre las rodillas"]},"supine-straddle":{"name":"Montar a horcajadas en posición supina","goodFor":"Estiramiento de piernas anchas asistido por gravedad.","instructions":"Bájese en el suelo y colóquese en posición supina a horcajadas con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"waterfall":{"name":"Postura de la cascada","goodFor":"Inversión suave y drenaje de piernas sin pared.","instructions":"Acuéstese boca arriba cerca de una pared (o levante las piernas sin una pared). Extienda las piernas hacia arriba para que los talones queden por encima de las caderas. Los brazos descansan a los lados, con las palmas hacia arriba. Suaviza el rostro y el vientre. Respira tranquilamente. Para salir, doble las rodillas y gire hacia un lado antes de sentarse.","breathCue":"Respiraciones largas y suaves; ojos suaves.","avoidIf":["Glaucoma/PIC alta no controlada: mantenga las piernas más bajas"],"props":["reforzar debajo de las caderas","muro"]},"wind-removing":{"name":"Rodillas al pecho","goodFor":"Alivio de la espalda baja y apoyo a la digestión.","instructions":"Acuéstese boca arriba. Abrace una o ambas rodillas contra el pecho. Suaviza los hombros y la mandíbula. Mécete suavemente si te sientes bien. Respire hacia la parte baja de la espalda. Para salir, suelte los pies al suelo.","breathCue":"Exhala abrazo; Inhale y suelte ligeramente."},"bow":{"name":"Postura del arco","goodFor":"Estiramiento profundo del frente del cuerpo con fuerza en la espalda.","instructions":"Acuéstese boca abajo. Doble las rodillas y estire hacia atrás para sujetar los tobillos o los pies externos. Patea los pies hacia las manos para levantar el pecho y los muslos. Suaviza el cuello. Respira hacia el vientre. Para salir, suelta los pies y baja lentamente.","breathCue":"Inhala patada en las manos; respirar hacia el vientre.","modifications":["Medio arco de un lado a la vez"]},"half-bow":{"name":"Medio arco","goodFor":"Flexión hacia atrás asimétrica y estiramiento cuádruple.","instructions":"Vaya al suelo y establezca Half Bow con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"childs":{"name":"Postura del niño","goodFor":"Descanso, liberación de la espalda y descenso del sistema nervioso.","instructions":"Arrodíllese con los dedos gordos del pie juntos y las rodillas a la altura de las caderas o más anchas. Sienta las caderas hacia los talones y dobla el torso hacia adelante, con la frente hacia la colchoneta. Los brazos se extienden hacia adelante o descansan a los lados. Suaviza el vientre y la mandíbula. Respire hacia las costillas traseras. Para salir, introduzca las manos y levántese lentamente hasta arrodillarse.","breathCue":"Exhale y suavice el abdomen hacia los muslos.","modifications":["rodillas anchas","Brazos al lado del cuerpo"],"props":["manta entre pantorrillas y muslos"]},"cobra":{"name":"Postura de la cobra","goodFor":"Fuerza de espalda y apertura del pecho.","instructions":"Acuéstese boca abajo, con la parte superior de los pies sobre la colchoneta y las manos debajo de los hombros. Presione ligeramente en las manos para levantar el cofre; Los codos permanecen suaves y cerca del cuerpo. El hueso púbico permanece abajo. Hombros alejados de las orejas. Para salir, baje el pecho con control.","breathCue":"Inhalar elevación; mantener la pelvis pesada.","modifications":["Mantenga los codos doblados","Manos más adelante"]},"reverse-corpse":{"name":"Cadáver inverso","goodFor":"Postura de reposo boca abajo; Savasana alternativa.","instructions":"Configure Reverse Corpse con accesorios cerca para que pueda descansar por completo. Apoye el cuerpo para que los músculos no se agarren; agregue mantas debajo de las rodillas, la columna o los brazos según sea necesario. Cierra los ojos si te sientes cómodo y deja que la respiración se vuelva tranquila y natural. Manténgase suave en la cara y el vientre. Para salir, muévase lentamente: gire hacia un lado y haga una pausa antes de sentarse."},"puppy":{"name":"Postura del cachorro","goodFor":"Apertura de hombros y parte superior de la espalda sin postura completa de niño.","instructions":"Desde la mesa, camine con las manos hacia adelante y mantenga las caderas apiladas sobre las rodillas. Baje el pecho y la frente (o la barbilla) hacia la colchoneta. Brazos activos; Los hombros se derriten. Suaviza el vientre. Para salir, pase las manos hacia atrás debajo de los hombros.","breathCue":"Exhala, derrite el cofre; las caderas se mantienen altas.","props":["frente en un bloque"]},"frog":{"name":"Postura de rana","goodFor":"Estiramiento cuádruple profundo y apertura en la parte delantera del cuerpo.","instructions":"Desde cuatro patas o boca abajo, abra bien las rodillas y alinee los pies con las rodillas, con los tobillos flexionados. Baje hasta los antebrazos si se siente cómodo. Suaviza las caderas: utiliza almohadillas debajo de las rodillas. Para salir, lleve las rodillas hacia adentro y siéntese de espaldas al Niño."},"locust-i":{"name":"Langosta que poso","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia de Locust I Pose.","instructions":"Acérquese al suelo y configure Locust I Pose con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar.","breathCue":"Inhalar elevación; exhalar alargar."},"locust-ii":{"name":"Postura de langosta II","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura Locust II.","instructions":"Bájese en el suelo y establezca la postura Locust II con presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"locust-iii":{"name":"Postura de langosta III","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura Locust III.","instructions":"Bájese en el suelo y establezca la postura Locust III con presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"sage-gherandas":{"name":"Sabio Gheranda\\\\","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Sage Gheranda\\\\","instructions":"Siéntese erguido, coloque las piernas y gírelas o dóblelas como se enseña en esta sabia variación. Alargue la columna al inhalar antes de profundizar. Suaviza los hombros. Para salir, suelte el giro o pliegue y estire las piernas."},"snake":{"name":"Postura de la serpiente","goodFor":"Apertura del pecho con fuerza en la parte superior de la espalda.","instructions":"Vaya al suelo y establezca la postura de la serpiente con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"sphinx":{"name":"Postura de la esfinge","goodFor":"Suave flexión hacia atrás; desarrolla la conciencia de la espalda baja.","instructions":"Acuéstese boca abajo. Apoye los antebrazos con los codos debajo de los hombros. Presione los antebrazos hacia abajo para levantar el pecho suavemente. Piernas largas y activas. Suaviza los hombros. Para salir, baje el pecho y apoye una mejilla en la colchoneta.","breathCue":"Inhale fácilmente hacia la parte baja del abdomen y el pecho."},"tortoise":{"name":"Postura de la tortuga","goodFor":"Doblez profundo hacia adelante y liberación de hombros.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Organice las piernas para la postura de la tortuga, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"table":{"name":"Postura de mesa","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de la mesa.","instructions":"Ponte de rodillas y manos. Coloque los hombros sobre las muñecas y las caderas sobre las rodillas. Separe los dedos; presione el piso para alejarlo. Mantenga la columna larga y el cuello neutral. Suaviza los codos. Para salir, siéntese junto al Niño o adopte su siguiente postura.","breathCue":"Respiración neutra y constante.","modifications":["Rellenar las rodillas"]},"camel":{"name":"Postura del camello","goodFor":"Estiramiento profundo de la parte delantera del cuerpo y apertura del corazón.","instructions":"Arrodíllate con las rodillas a la altura de las caderas. Manos en la espalda baja o alcanzar los talones. Levante el cofre y arquee suavemente la espalda; Mantenga las caderas sobre las rodillas. Suavizar la garganta; Mirar hacia arriba sólo si el cuello está contento. Para salir, lleva las manos a la espalda baja y levanta el pecho para volver a la posición vertical.","breathCue":"Inhale, levante el cofre; Exhale las manos hacia los talones sólo si es seguro.","modifications":["Manos en el sacro","dedos de los pies metidos"],"avoidIf":["Lesión en el cuello: mantenga la barbilla ligeramente metida, sin dejar caer la cabeza."],"props":["bloques por los talones"]},"cat":{"name":"Postura del gato","goodFor":"Movilidad espinal y movimiento relacionado con la respiración.","instructions":"Vaya al suelo y establezca la postura del gato con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar.","breathCue":"Exhale redondo; inhala, prepárate para la vaca."},"cow":{"name":"Postura de la vaca","goodFor":"Extensión de la columna y apertura del tórax combinadas con Cat.","instructions":"Vaya al suelo y establezca la postura de la vaca con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar.","breathCue":"Inhala levanta el corazón; mirada suave."},"cat-cow":{"name":"gato-vaca","goodFor":"Calienta la columna y vincula la respiración con el movimiento.","description":"Alterne gato y vaca con la respiración: redonda al exhalar, arqueada al inhalar. Por lo general, varias rondas, no dos agarres estáticos.","instructions":"Comience con las manos y las rodillas, los hombros sobre las muñecas y las caderas sobre las rodillas. Inhala para dejar caer el vientre y levantar el pecho y mirar (vaca). Exhala para redondear la columna, mete la cola y mira hacia el ombligo (gato). Fluye con la respiración. Para salir, regrese a una columna de mesa neutral.","breathCue":"Inhale hacia la vaca (vientre suave, corazón hacia adelante); exhale al gato (alrededor de la columna). Sigue alternando durante varias rondas.","modifications":["Rellenar las rodillas","Menos rondas si las muñecas son sensibles"],"alignmentCues":["Muñecas debajo de los hombros, rodillas debajo de las caderas.","Muévete con la respiración: una forma por inhalación o exhalación."]},"dolphin":{"name":"Postura del delfín","goodFor":"Fuerza de hombros y variación Downdog en antebrazos.","instructions":"Desde los antebrazos y las rodillas, meta los dedos de los pies y levante las caderas formando una V invertida sobre los antebrazos. Codos a la altura de los hombros; junte las manos o mantenga los antebrazos paralelos. Suaviza las rodillas para que la columna se alargue. Los talones llegan hasta abajo. Para salir, baje las rodillas hasta la colchoneta.","breathCue":"Exhalaciones largas; cuello suave.","modifications":["rodillas abajo","Codos más anchos"]},"downward-facing-dog":{"name":"Postura del perro boca abajo","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del perro boca abajo.","instructions":"Desde las manos y las rodillas, doble los dedos de los pies, levante las caderas y estire las piernas formando una V invertida. Las manos a la altura de los hombros y los pies a la altura de las caderas. Presione uniformemente en las palmas; alargar la columna hacia las caderas. Suaviza las rodillas si es necesario para que la espalda se mantenga larga. Los talones llegan al suelo sin forzar. Respiraciones largas y suaves. Para salir, deje caer las rodillas o dé un paso/salte hacia adelante.","breathCue":"Respiraciones largas y suaves; mandíbula relajada.","modifications":["doblar las rodillas","Ampliar la postura"],"deepen":["Presione los muslos hacia atrás; talones hacia el suelo sin forzar"],"avoidIf":["Presión arterial alta no controlada: mantenga la cabeza más alta"],"commonMistakes":["Parte superior de la espalda redondeada","Volcando sobre los hombros"],"alignmentCues":["Manos a la altura de los hombros","Las caderas se extienden hacia arriba y hacia atrás."],"props":["bloques bajo las manos","manta debajo de los talones"]},"eight-point":{"name":"Postura de ocho puntos","goodFor":"Fuerza de transición clásica de Ashtanga.","instructions":"Desde las manos y las rodillas o desde una tabla modificada, baje el pecho y la barbilla hacia la colchoneta mientras las caderas permanecen elevadas (las rodillas, el pecho y la barbilla se tocan). Los codos se abrazan. Para salir, deslícese hacia adelante hasta Cobra o empújese hacia atrás hacia Niño."},"humble-flamingo":{"name":"Postura del flamenco humilde","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Humble Flamingo Pose.","instructions":"Desde una posición de flamenco o bailarina de pie, inclínese hacia adelante mientras sostiene el pie levantado, llevando el torso hacia la pierna de apoyo. Suaviza la rodilla de apoyo. Para salir, levántate y suelta el pie."},"gate":{"name":"Postura de la puerta","goodFor":"Longitud lateral del cuerpo y espacio para respirar.","instructions":"Arrodíllate y luego extiende una pierna hacia un lado con el pie apoyado en el suelo. Lleve el brazo del mismo lado hacia abajo por la pierna extendida; el brazo superior se arquea por encima de la cabeza. Mantenga las caderas cuadradas hacia el frente. Suaviza la cintura lateral. Para salir, levante el torso y vuelva a meter la rodilla extendida."},"horse":{"name":"Postura del caballo","goodFor":"Apertura de cadera con desafío de equilibrio inusual.","instructions":"Adopte una postura amplia con los dedos de los pies hacia afuera. Doble las rodillas profundamente sobre los dedos de los pies y siente las caderas bajas, similar a la Diosa. Manos en el corazón o en los muslos. Lomo alto. Para salir, estire las piernas y junte los pies."},"lizard":{"name":"Postura del lagarto","goodFor":"Intensa apertura de cadera e ingle.","instructions":"Desde una estocada baja, camine con ambas manos dentro del pie delantero y bájelas sobre los antebrazos si está disponible (o mantenga las manos sobre los bloques). Los dedos delanteros pueden salir ligeramente. Suaviza la rodilla trasera o mantenla levantada. Respire hacia la parte interna de la cadera. Para salir, planta las manos, da un paso atrás y cambia de lado más tarde.","breathCue":"Exhale, mueva las caderas hacia adelante con comodidad.","props":["bloques bajo las manos","manta debajo de la rodilla trasera"]},"lunge":{"name":"Estocada clásica","goodFor":"Estocada de transición utilizada en saludos al sol.","instructions":"Da un paso adelante entre las manos con la pierna trasera larga y fuerte (talón hacia arriba). Apila la rodilla delantera sobre el tobillo. Las manos enmarcan el pie delantero o lo levantan. Mantenga las caderas niveladas y la columna alargada. Respira constantemente. Para salir, retroceda el pie delantero o levántese hasta ponerse de pie.","breathCue":"Longitud de la inhalación; exhale, ajuste las caderas.","modifications":["Rodilla hacia atrás","Manos en bloques"],"alignmentCues":["Rodilleras delanteras sobre el tobillo.","Talón trasero apilado debajo de los dedos"]},"crooked-monkey":{"name":"Postura del mono torcido","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del mono torcido.","instructions":"Desde una preparación de estocada o equilibrio de brazos, coloque las piernas en forma de mono torcido e inclínese sobre las manos para levantarlas, si está disponible. Suaviza los codos. Para salir, baje y suelte la atadura con cuidado."},"pigeon":{"name":"Postura de la paloma","goodFor":"Apertura profunda de la cadera; Prepárate para posturas sentadas.","instructions":"Vaya al suelo y establezca Pigeon Pose con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"one-legged-king-pigeon":{"name":"Postura de la paloma real con una sola pierna","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de la paloma real con una sola pierna.","instructions":"Desde Half Pigeon, doble la rodilla trasera y alcance el pie con una o ambas manos (use una correa). Patea suavemente la mano para abrir el cofre. Mantenga la cadera delantera apoyada. Para salir, suelte primero el pie trasero y luego retroceda hasta Down Dog."},"plank":{"name":"Postura de la tabla","goodFor":"Resistencia central y estabilidad del hombro.","instructions":"Desde las manos y las rodillas o en una posición de flexión, coloque los hombros sobre las muñecas y retroceda los pies. Forma una línea larga desde los talones hasta la coronilla. Presione el piso; dibuja el ombligo suavemente hacia adentro. Piernas fuertes; talones llegando hacia atrás. Suaviza la mandíbula y respira constantemente. Para salir, baje las rodillas o muévase hacia Chaturanga o Down Dog.","breathCue":"Respiración constante; no contengas la respiración.","modifications":["rodillas abajo","Manos en bloques"],"deepen":["Empuje el piso; una larga fila"],"avoidIf":["Dolor agudo en la muñeca: use los puños o los antebrazos"],"commonMistakes":["Caderas caídas","Hombros cayendo hacia las orejas"],"alignmentCues":["Presione los montículos de los dedos índices.","Dibuja el ombligo suavemente hacia adentro"]},"upward-plank":{"name":"Plancha hacia arriba","goodFor":"Fuerza de la cadena posterior y estiramiento del cuerpo anterior.","instructions":"Siéntate con las piernas extendidas, las manos detrás de las caderas y los dedos hacia adelante o hacia afuera. Presione las manos y los pies para levantar las caderas; los dedos de los pies pueden apuntar hacia abajo. Suaviza el cuello o mira hacia adelante. Para salir, baja las caderas y siéntate."},"four-limbed-staff":{"name":"Postura del bastón de cuatro extremidades","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del bastón de cuatro extremidades.","instructions":"Desde la tabla, doble los codos hacia atrás a lo largo de las costillas y baje el cuerpo hasta la mitad, manteniéndolo paralelo al suelo. Mantenga el pecho ancho y los hombros a la altura del codo. Involucre el núcleo y las piernas. Mira ligeramente hacia adelante. Exhala mientras bajas. Para salir, baje completamente o presione hacia arriba en Upward Dog o Cobra.","breathCue":"Exhala para bajar con control.","modifications":["Rodillas-pecho-barbilla","Saltar y pasar a cachorro o niño"],"avoidIf":["Ensanchamiento por pinzamiento del hombro"],"commonMistakes":["Codos extendidos","Cofre colapsado"],"alignmentCues":["Los codos abrazan las costillas.","Hombros a la altura del codo"]},"flying-warrior":{"name":"Postura del guerrero volador","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del guerrero volador.","instructions":"Desde Warrior III o una estocada, busque una variación de atadura o brazo que se levante hasta adoptar una forma voladora, si está disponible, o permanezca en una línea fuerte de Warrior III. Suaviza la rodilla de apoyo. Para salir, baje con control."},"side-plank":{"name":"Plancha lateral","goodFor":"Fuerza central lateral y estabilidad del hombro.","instructions":"Desde la tabla, pase al borde exterior de un pie y apile o escalone los pies. La parte inferior del brazo se coloca debajo del hombro; el brazo superior llega hacia arriba o hasta la cadera. Levantamiento de caderas; cuerpo en una larga fila. Mirada suave. Para salir, vuelva a la plancha o baje las rodillas."},"extended-side-plank":{"name":"Plancha lateral extendida","goodFor":"Fuerza avanzada del core lateral y del hombro.","instructions":"Desde la plancha lateral, levante la pierna superior y/o alcance el brazo superior por encima para abrir el cuerpo lateral. Mantenga estable el hombro inferior. Mirada suave. Para salir, baja la pierna superior y regresa a Side Plank o plancha."},"inverted-staff":{"name":"Postura del bastón invertido","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del bastón invertida.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura del bastón invertido, luego alargue la columna mientras inhala antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"little-thunderbolt":{"name":"Pequeño rayo","goodFor":"Flexión profunda hacia atrás de rodillas.","instructions":"Baja al suelo y coloca Little Thunderbolt con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"tiger":{"name":"Postura del tigre","goodFor":"Movilidad espinal y activación de glúteos.","instructions":"Vaya al suelo y establezca la postura del tigre con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"upward-facing-dog":{"name":"Postura del perro mirando hacia arriba","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del perro mirando hacia arriba.","instructions":"Tumbado boca abajo o desde Chaturanga, presione las manos y estire los brazos para levantar el pecho. La parte superior de los pies presiona hacia abajo; los muslos se levantan de la colchoneta. Eche los hombros hacia atrás; ampliar las clavículas. Mira suavemente hacia adelante o ligeramente hacia arriba. Inhala para abrir. Para salir, meta los dedos de los pies y levante las caderas hacia Down Dog, o bájelas hasta el abdomen.","breathCue":"Inhala para abrir el cofre; piernas fuertes.","modifications":["Cobra con los muslos hacia abajo","Almohadilla debajo de las caderas"],"avoidIf":["Dolor lumbar agudo: prefiera cobra"],"commonMistakes":["hombros encogidos","Pies perezosos"],"alignmentCues":["La parte superior de los pies presiona hacia abajo","levantamiento de muslos"]},"wheel":{"name":"Postura de la rueda","goodFor":"Fuerza de flexión hacia atrás profunda y apertura del pecho.","instructions":"Acuéstese boca arriba, doble las rodillas, coloque las manos junto a las orejas con los dedos hacia los hombros. Presione las manos y los pies para levantarlo formando un arco. Suavizar el cuello; mantener el peso uniforme. Respire constantemente, no contenga la respiración. Para salir, meta ligeramente la barbilla y baje con control sobre los hombros y luego hacia atrás.","breathCue":"Respiración constante; nunca lo sostengas para empujar más fuerte.","modifications":["Quédate en el puente","Manos en bloques"],"avoidIf":["Presión arterial alta no controlada","Lesión en la muñeca","Embarazo"],"props":["bloques bajo las manos","muro"]},"wild-thing":{"name":"cosa salvaje","goodFor":"Apertura del corazón con fuerza en hombros y cadera.","instructions":"Baja al suelo y coloca Wild Thing con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"both-feet-behind-the-head-ii":{"name":"Postura de ambos pies detrás de la cabeza II","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de ambos pies detrás de la cabeza II.","instructions":"Desde una posición sentada, lleve ambos pies detrás de la cabeza sólo con extrema movilidad y preparación previa, nunca fuerce. Suaviza el cuello y la mandíbula. Para salir, suelta un pie a la vez con las manos."},"chin-stand":{"name":"Postura de soporte de barbilla","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de soporte de barbilla.","instructions":"Vaya al suelo y establezca la postura de soporte para la barbilla con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"crane":{"name":"Postura de la grulla","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Crane Pose.","instructions":"Desde una sentadilla, plante las manos y coloque las rodillas en lo alto de la parte superior de los brazos (familia Cuervo/Grúa). Inclínese hacia adelante, mire hacia adelante y levante los pies. Redondea ligeramente la espalda; enganchar el núcleo. Para salir, baje los pies hasta ponerse en cuclillas.","breathCue":"Respiraciones cortas y constantes; ojos suaves hacia adelante.","modifications":["Pies en un bloque","Un pie se levanta"],"avoidIf":["dolor de muñeca"],"props":["manta debajo de la cara para rescates"]},"crow":{"name":"Postura del cuervo","goodFor":"Equilibrio de brazos, fuerza y ​​concentración."},"deaf-mans":{"name":"La postura del hombre sordo","goodFor":"Variación de inversión calmante; Silenciar el pliegue hacia adelante boca abajo.","instructions":"Vaya al suelo y establezca la postura del hombre sordo con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"eight-angle":{"name":"Postura de ocho ángulos","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de ocho ángulos.","instructions":"Desde un giro o sentadilla sentado, enganche un muslo en la parte superior del brazo, plante las manos y cruce los tobillos mientras levanta y gira. Núcleo fuerte; mirar hacia adelante. Para salir, baja las caderas y desenreda las piernas."},"elbow-balance":{"name":"Postura de equilibrio del codo","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de equilibrio del codo.","instructions":"Vaya al suelo y establezca la postura de equilibrio del codo con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"elephant-trunk":{"name":"Postura de la trompa de elefante","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de la trompa de elefante.","instructions":"Desde una posición sentada, coloque una pierna sobre la parte superior del brazo (trompa de elefante), plante las manos y levante. Suaviza el cuello. Para salir, baja la cadera y suelta la pierna."},"firefly":{"name":"Postura de luciérnaga","goodFor":"Fuerza del equilibrio del brazo con compromiso de los isquiotibiales.","instructions":"Desde una sentadilla, pase los hombros por debajo de los muslos, plante las manos y estire las piernas hacia los lados mientras levanta. Suaviza ligeramente los codos. Mirar hacia adelante. Para salir, flexiona las rodillas y baja los pies."},"floating-stick":{"name":"Postura del palo flotante","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del bastón flotante.","instructions":"Desde un soporte para brazos sentado o en forma de tabla, active el núcleo y levante las piernas formando una línea similar a un palo. Suaviza el cuello. Para salir, baje las caderas o los pies con control."},"flying-man":{"name":"Postura del hombre volador","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Flying Man Pose.","instructions":"Baja al suelo y establece la postura del hombre volador con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"revolved-flying-man":{"name":"Pose de hombre volador girado","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del hombre volador girado.","instructions":"Acérquese al suelo y establezca la postura del hombre volador giratorio con presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"two-legged-sage-koundinyas":{"name":"Sabio Koundinya de dos patas\\\\","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Two Legged Sage Koundinya\\\\","instructions":"Desde una preparación de equilibrio de brazos torcidos, plante las manos, enganche ambas piernas sobre la parte superior de un brazo e inclínese hacia adelante para levantar. Mirar hacia adelante; codos suaves. Para salir, baje los pies y desenrosque."},"side-crow":{"name":"Cuervo lateral","goodFor":"Girar el brazo equilibra la fuerza y ​​la concentración.","instructions":"Desde una sentadilla torcida, coloque ambas manos a los lados de las piernas e incline las rodillas sobre la parte superior de los brazos. Mira hacia adelante y levanta los pies. Involucrar el núcleo. Para salir, baje los pies con control."},"forearm-balance":{"name":"Equilibrio del antebrazo","goodFor":"Fuerza de inversión y estabilidad del hombro.","instructions":"Utilice el equilibrio del antebrazo como forma de enlace entre posturas. Coloque las manos y los pies con una alineación clara, luego muévase con la respiración en lugar del impulso. Mantenga el núcleo ligeramente enganchado y el cuello largo. Quédese sólo mientras la respiración sea suave. Para salir, pasa a la siguiente postura de tu secuencia o deja caer las rodillas para descansar."},"dragonfly":{"name":"Postura de libélula","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Dragonfly Pose.","instructions":"Desde un asiento con las piernas anchas o una preparación para el equilibrio de los brazos, apoye las piernas en la parte superior de los brazos e inclínese hacia adelante para levantar. Suaviza el cuello. Para salir, baja con control y sacude las piernas."},"handstand":{"name":"parada de manos","goodFor":"Fuerza de inversión total y propiocepción.","instructions":"Desde Down Dog o una estocada contra la pared, coloque las manos a la altura de los hombros y patee o flote una pierna hacia arriba y luego la otra. Brazos fuertes; mirada entre las manos o ligeramente hacia adelante. Suaviza la mandíbula. Para salir, baje un pie a la vez con control."},"supported-headstand":{"name":"Parada de cabeza apoyada","goodFor":"Inversión clásica para concentrarse y fortalecer la parte superior del cuerpo.","instructions":"Bájese en el suelo y establezca la parada de cabeza con apoyo ejerciendo una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"tripod-headstand":{"name":"Postura del trípode sobre la cabeza","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de trípode sobre la cabeza.","instructions":"Vaya al suelo y establezca la postura de trípode sobre la cabeza con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"flying-lizard":{"name":"Postura del lagarto volador","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del lagarto volador.","instructions":"Baja al suelo y establece la postura del lagarto volador con presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"peacock":{"name":"Postura del pavo real","goodFor":"Fuerza intensa en el core y la muñeca.","instructions":"Vaya al suelo y establezca la postura del pavo real con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"pendant":{"name":"Pose colgante","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura colgante.","instructions":"Comience de pie con pies firmes y una mirada suave. Organice el cuerpo en postura colgante: coloque los pies primero, luego las manos o los brazos, luego alargue la columna. Suaviza cualquier articulación que se sienta comprimida; mantén la respiración tranquila. Sostenga a una profundidad que pueda sostener sin agarrar la mandíbula. Para salir, invertir la entrada con control y volver a montaña o hacer un pliegue hacia adelante antes de continuar."},"flying-pigeon":{"name":"Postura de la paloma voladora","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para Flying Pigeon Pose.","instructions":"Vaya al suelo y establezca la postura de la paloma voladora con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"plow":{"name":"Postura del arado","goodFor":"Estiramiento posterior e inversión calmante.","instructions":"Desde la preparación acostada o parada sobre los hombros, levante las piernas por encima de la cabeza y baje los dedos de los pies hacia el suelo detrás de usted, si está disponible. Apoye la espalda con las manos o mantenga los brazos en el suelo. Suaviza el cuello, nunca gires la cabeza. Para salir, baje lentamente con las rodillas dobladas y las manos apoyadas.","breathCue":"Aliento suave; salir si hay presión en la cabeza/cuello.","modifications":["Pies a una silla","rodillas dobladas"],"avoidIf":["Lesión en el cuello","Glaucoma"],"props":["manta debajo de los hombros"]},"rooster":{"name":"Postura del gallo","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del gallo.","instructions":"Desde un asiento de loto o con las piernas atadas, plante las manos e intente levantar el cuerpo (equilibrio del gallo). Suavizar el cuello; levante sólo lo más alto que esté estable. Para salir, baja las caderas con cuidado y desdobla las piernas."},"scorpion":{"name":"Postura del escorpión","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura del escorpión.","instructions":"Vaya al suelo y establezca la postura del escorpión con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"shoulder-pressing":{"name":"Postura de presión de hombros","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de presión de hombros.","instructions":"Vaya al suelo y establezca la postura de presión de hombros con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"shoulder-stand-with-lotus-legs":{"name":"Postura de soporte sobre los hombros con piernas de loto","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de hombros con postura de piernas de loto.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la posición de hombros con postura de piernas de loto, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"supported-shoulder-stand":{"name":"Postura de soporte de hombro con apoyo","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de soporte con hombros apoyados.","instructions":"Vaya al suelo y establezca la postura de soporte con hombros apoyados con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar.","breathCue":"Aliento suave y libre; Nunca gires la cabeza.","modifications":["Piernas en la pared en su lugar"],"avoidIf":["Lesión en el cuello","Glaucoma","Menstruación (precaución tradicional)","Embarazo"],"props":["mantas debajo de los hombros","muro"]},"bound-revolved-chair":{"name":"Postura de silla giratoria atada","goodFor":"Desarrolla movilidad, fuerza y ​​conciencia para la postura de silla giratoria atada.","instructions":"Desde la silla, lleva las manos al corazón y gira el torso hacia un lado, enganchando el codo opuesto por fuera del muslo. Presione el brazo contra la pierna para profundizar el giro; Alargue la columna en cada inhalación. Suaviza las rodillas de manera uniforme. Mira más allá del hombro. Para salir, desenrosque hacia el centro y estire las piernas."},"forward-fold":{"name":"Plegado hacia adelante de pie","goodFor":"Longitud de los isquiotibiales, calmando el sistema nervioso, inversión suave."},"halfway-lift":{"name":"Elevación a mitad de camino","goodFor":"Longitud de la columna y preparación para pliegues o posturas de pie."},"warrior-1":{"name":"guerrero yo","goodFor":"Apertura de cadera, fuerza de piernas y expansión del pecho."},"warrior-2":{"name":"Guerrero II","goodFor":"Resistencia, movilidad de la cadera y resistencia del hombro."},"warrior-3":{"name":"Guerrero III","goodFor":"Equilibrio, fuerza de la cadena posterior y concentración."},"reverse-warrior":{"name":"Guerrero inverso","goodFor":"Estiramiento lateral con fuerza continua en la parte inferior del cuerpo.","instructions":"Desde Warrior II, mantenga la rodilla delantera doblada y deslice la mano trasera por la pierna trasera. Lleve el brazo delantero hacia arriba y ligeramente hacia atrás, abriendo el cuerpo lateral. Suavizar el cuello; Mira hacia arriba sólo si te sientes cómodo. La rodilla delantera permanece sobre el tobillo. Para salir, devuelva el torso erguido al Guerrero II.","breathCue":"Inhale, levante el brazo superior; exhale y mantenga fuerte el muslo delantero.","modifications":["Mano en el muslo delantero en lugar de en la pierna trasera."]},"wide-forward-fold":{"name":"Plegado hacia adelante con las piernas anchas","goodFor":"Estiramiento de la parte interna del muslo y del tendón de la corva; pliegue hacia adelante calmante."},"standing-split":{"name":"División de pie","goodFor":"Longitud de los isquiotibiales, equilibrio e inversión leve."},"down-dog":{"name":"Perro boca abajo","goodFor":"Restablecimiento de todo el cuerpo, fuerza de los hombros y estiramiento de la cadena posterior."},"up-dog":{"name":"Perro mirando hacia arriba","goodFor":"Fuerza de espalda, apertura de pecho y contraposición a pliegues."},"chaturanga":{"name":"Bastón de cuatro extremidades","goodFor":"Fuerza de brazos y core para transiciones de vinyasa."},"tabletop":{"name":"Superficie de la mesa","goodFor":"Base de alineación neutra para trabajos en piso."},"thread-needle":{"name":"Enhebrar la aguja","goodFor":"Liberación de la parte superior de la espalda y suave giro torácico.","instructions":"Desde la mesa, deslice un brazo debajo de la axila opuesta, con la palma hacia arriba, descansando sobre el hombro y la oreja. La otra mano permanece plantada o se extiende hacia arriba o alrededor. Suavizar en el giro. Respire hacia la parte superior de la espalda. Para salir, presione la mano de apoyo y desenrosque hacia la mesa.","breathCue":"Exhale, enhebre el brazo; Inhale el espacio entre las palas."},"locust":{"name":"Postura de langosta","goodFor":"Fuerza de la cadena posterior para la postura."},"supine-twist":{"name":"Giro supino","goodFor":"Movilidad espinal y liberación lumbar."},"knees-to-chest":{"name":"Rodillas al pecho","goodFor":"Alivio de la espalda baja y apoyo a la digestión."},"figure-four":{"name":"Figura cuatro reclinada","goodFor":"Lanzamiento de la región de la cadera exterior y de la banda IT.","instructions":"Acuéstese boca arriba. Cruza un tobillo sobre el muslo opuesto. Pase las manos detrás del muslo no cruzado (o sobre la espinilla) y meta las piernas. Mantenga la cabeza y los hombros relajados sobre la colchoneta. Suaviza la mandíbula. Para salir, suelte las piernas y cambie o plante los pies.","breathCue":"Exhale y suavice las caderas hacia el suelo.","modifications":["Cabeza sobre una almohada"],"props":["correa alrededor de la espinilla"]},"butterfly":{"name":"Postura de mariposa","goodFor":"Estiramiento de la parte interna del muslo y movilidad de la cadera."},"seated-forward-fold":{"name":"Plegado hacia adelante sentado","goodFor":"Longitud de los isquiotibiales y pliegue hacia adelante relajante."},"wide-seated-fold":{"name":"Plegado sentado de gran angular","goodFor":"Flexibilidad de piernas anchas y estiramiento en la parte interna del muslo."},"seated-twist":{"name":"Giro sentado","goodFor":"Movilidad espinal y masaje digestivo."},"legs-up-wall":{"name":"Piernas arriba de la pared","goodFor":"Recuperación, circulación e inversión calmante."},"reclining-butterfly":{"name":"Mariposa reclinada","goodFor":"Apertura reparadora de cadera y alivio del estrés.","instructions":"Acuéstese boca arriba. Junta las plantas de los pies y deja que las rodillas se abran. Apoye la parte externa de los muslos con mantas si es necesario. Los brazos descansan a los lados. Suaviza el vientre. Para salir, utiliza las manos para cerrar las rodillas y rueda hacia un lado."},"easy-seat":{"name":"Asiento fácil","goodFor":"Asiento de meditación y suave apertura de cadera."},"half-split":{"name":"Medias divisiones","goodFor":"Estiramiento dirigido a los isquiotibiales con soporte para las rodillas."},"shoulder-stand":{"name":"Soporte de hombro","goodFor":"Beneficios de la inversión, tradición de estimulación tiroidea, fuerza central."},"revolved-chair":{"name":"Silla giratoria","goodFor":"Fuerza de piernas con giro desintoxicante."},"supine-hand-to-toe":{"name":"Mano en decúbito supino hasta el dedo gordo del pie","goodFor":"Estiramiento controlado de los isquiotibiales con estabilidad pélvica."},"crescent":{"name":"Estocada creciente","goodFor":"Estiramiento de flexores de cadera con elevación energizante."},"hand-to-big-toe":{"name":"De la mano al dedo gordo del pie","goodFor":"Longitud de los isquiotibiales con equilibrio y concentración."},"extended-hand-to-big-toe":{"name":"Mano extendida hasta el dedo gordo","goodFor":"Apertura exterior de cadera con equilibrio en una sola pierna."},"head-to-knee":{"name":"De cabeza a rodilla","goodFor":"Estiramiento asimétrico de los isquiotibiales y pliegue calmante."},"marichi":{"name":"Postura de la salvia Marichi","goodFor":"Pliegue hacia adelante con un estiramiento del hombro."},"marichi-twist":{"name":"Giro de salvia y marichi","goodFor":"Giro sentado para movilidad espinal y digestión."},"archer":{"name":"Postura del arquero","goodFor":"Abertura de cadera e isquiotibial con cierre sentado."},"crow-kakasana":{"name":"Cuervo (Kakasana)","goodFor":"Equilibrio fundamental del brazo."},"locust-arms":{"name":"Armas de langosta hacia adelante","goodFor":"Fuerza de la cadena posterior con resistencia del hombro."},"wide-forward-side":{"name":"Pliegue lateral de piernas anchas","goodFor":"Estiramiento de los isquiotibiales con longitud lateral del cuerpo."},"revolved-wide-fold":{"name":"Pliegue giratorio de patas anchas","goodFor":"Pliegue de pernera ancha con giro."},"upward-plank-prep":{"name":"Preparación de la tabla hacia arriba","goodFor":"Se construye hacia la tabla ascendente completa.","instructions":"Vaya al suelo y configure Upward Plank Prep con una presión uniforme en las manos, las rodillas o las caderas. Alargue la columna antes de agregar esfuerzo. Muévase hacia la forma exhalando si cierra el cuerpo, o inhalando si abre el pecho. Mantenga la mandíbula y los hombros suaves. Para salir, baje con control y haga una pausa en un descanso neutro antes de continuar."},"sage-marichis-ii":{"name":"Pose II de la sabia Marichi","goodFor":"Abertura en cadera con pliegue y ribete hacia adelante.","description":"Un pie en medio loto, el otro pie plantado. Doble hacia adelante, envolviendo el brazo alrededor de la espinilla doblada.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura II de Sage Marichi, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"sage-marichis-iii":{"name":"Pose III de la sabia Marichi","goodFor":"Giro sentado para movilidad espinal y digestión.","description":"Una pierna extendida y el otro pie plantado. Gira hacia la rodilla doblada, abrazándola con el brazo opuesto.","instructions":"Siéntate con un pie plano y la otra pierna extendida o en forma de loto. Abrace la rodilla doblada y gire hacia ella, enganchando el brazo opuesto. Alargue la inhalación; gire al exhalar. Para salir, desenrosque y cambie.","breathCue":"Exhala para girar; Inhale para alargar la columna.","modifications":["Mantenga la pierna extendida suave","Mano atrás para apalancar"],"avoidIf":["Embarazo tardío: omita los giros cerrados profundos"]},"sage-marichis-iv":{"name":"Pose IV de la sabia Marichi","goodFor":"Giro avanzado sentado y abridor de cadera.","description":"Combine medio loto con un giro profundo y un enlace opcional. Muévase lentamente y mantenga ambos isquiones en el suelo.","instructions":"Siéntese erguido sobre los isquiones; use una manta doblada si la espalda baja se curva. Coloque las piernas para la postura IV de Sage Marichi, luego alargue la columna al inhalar antes de doblar, girar o atar. Suaviza los hombros lejos de las orejas. Respire constantemente; aliviar cualquier sensación aguda. Para salir, primero suelte las ataduras y luego descruce o estire las piernas lentamente."},"cross-legged-forward-fold":{"name":"Plegado hacia adelante con las piernas cruzadas","goodFor":"Liberación suave de la cadera y la espalda desde un pliegue sentado (Easy Seat sin el pliegue permanece como Easy Pose).","description":"Siéntate en una posición cómoda con las piernas cruzadas. Alargue la columna mientras inhala, luego gire las caderas para doblarse hacia adelante, extendiendo las manos frente a usted."},"knee-lift":{"name":"Levantamiento de rodilla","goodFor":"Calentamiento sencillo sobre equilibrio de pie y flexión de cadera.","description":"Párate con los pies juntos. Levanta un pie del suelo. Bloquee sus manos alrededor de su espinilla mientras levanta su rodilla hacia su pecho. Cambia de lado."},"kneeling":{"name":"De rodillas","goodFor":"Transición neutra entre el suelo y el trabajo de pie.","description":"Arrodíllate sobre la colchoneta. Mantenga la espalda recta y aleje los hombros de las orejas. Manos en las caderas."},"morning-stretch":{"name":"Estiramiento matutino","goodFor":"Suave alargamiento al despertar antes o después del trabajo en el suelo.","description":"Acuéstese boca arriba. Coloque sus brazos sobre la colchoneta por encima de su cabeza. Estire suavemente las manos y los dedos lejos de los pies y los dedos de los pies."},"opened-knee-lift":{"name":"Elevación de rodilla abierta","goodFor":"Equilibre con un suave abridor de cadera de pie.","description":"Párate con los pies juntos. Levante un pie del suelo para que su rodilla esté alineada con sus caderas. Agarre esa rodilla con la mano del mismo lado y lleve suavemente la pierna hacia afuera. Coloque la mano opuesta sobre la cadera. Cambia de lado."},"reclined-bent-knees":{"name":"Rodillas dobladas reclinadas","goodFor":"Descanso neutro que alivia la zona lumbar más que la pierna plana Cadáver para muchos cuerpos.","description":"Acuéstese boca arriba. Doble las rodillas y coloque las plantas de los pies en el suelo separadas a la altura de las caderas."},"seated-cactus-arms":{"name":"Brazos de cactus sentados","goodFor":"Abridor de pecho y hombros sentado; Combina bien con el trabajo de respiración.","description":"Siéntate erguido con los pies apoyados en el suelo o las piernas cruzadas. Levante los brazos hacia el cactus, los codos a 90°, los antebrazos verticales. Baja los hombros a medida que ensanchas el pecho."},"standing-back-bend":{"name":"Inclinación hacia atrás de pie","goodFor":"Suave apertura del corazón y restablecimiento de la postura.","description":"Manténgase erguido y con los pies firmes. Junte las manos y extiéndalas por encima de su cabeza. Levante el pecho y arquee suavemente la parte superior de la espalda mientras mantiene el núcleo comprometido y las piernas fuertes."},"standing-side-bend":{"name":"Curva lateral de pie","goodFor":"Estiramiento lateral de pie para el costado del cuerpo y el espacio para respirar.","description":"Párese erguido con los pies separados a la altura de las caderas. Levanta ambos brazos por encima de la cabeza y entrelaza los dedos. Doble lentamente la parte superior del cuerpo hacia un lado, manteniendo el pecho abierto y las caderas cuadradas. Cambia de lado."}}`),t={"sun-a-foundation":{name:`Fundación Saludo al Sol`,description:`Arco de calentamiento estándar: montaña → doblar → tabla → ciclos de perro para generar calor de forma segura antes de trabajar de pie.`,focus:`Vinyasa · calor`},"peak-warrior":{name:`Pico: Fuerza guerrera`,description:`Método de la pose de pico: columna cálida → saludo al sol con calor → guerreros en pico → abridores de cadera → giro → savasana.`,focus:`Pose máxima · guerreros`},"peak-wheel":{name:`Pico: Rueda hacia atrás`,description:`Preparación progresiva de flexión hacia atrás (patrón de postura máxima): flexores de cadera → extensión suave → puente → rueda → contrapliegues.`,focus:`Pose máxima · rueda`},"peak-crow":{name:`Pico: equilibrio del brazo de cuervo`,description:`Preparación de muñeca/núcleo y luego pico de cuervo (plantilla común de clase de equilibrio de brazos), con integración de piso blando.`,focus:`Pose máxima · cuervo`},"standing-flow":{name:`Clásico de flujo permanente`,description:`Bloque de pie clásico de clase media: guerreros, triángulo, equilibrio, pliegues anchos: el corazón de muchas clases de vinyasa.`,focus:`De pie · equilibrio`},"yin-hips":{name:`Yin: caderas e ingle`,description:`Plantilla yin moderna: pocas formas, posiciones largas (use Suave/45s+), rebote entre posturas, savasana larga.`,focus:`Yin · caderas`},"yin-spine":{name:`Yin: columna vertebral y costados del cuerpo`,description:`Enfoque de la columna Yin con suaves giros e inclinaciones laterales, terminando en un descanso prolongado.`,focus:`Yin · columna vertebral`},"restorative-evening":{name:`Noche reparadora`,description:`Cambio descendente del sistema nervioso: formas apoyadas, piernas arriba, esfuerzo mínimo: la mejor práctica nocturna común.`,focus:`Restaurativo`},"mobility-morning":{name:`Movilidad matutina`,description:`Llegada corta → calentamiento de las articulaciones → ponerse de pie fácilmente → enfriamiento en el suelo (arco de práctica diaria breve y popular).`,focus:`Cuerpo completo · gentil`},"hamstring-flow":{name:`Flujo de enfoque del tendón de la corva`,description:`Liberación progresiva de la línea de fondo (estiramiento reclinado → perro → media división → pirámide → pliegue sentado). Agarre sentado más largo; sin repeticiones de relleno.`,focus:`Isquiotibiales`},"hip-opener-modern":{name:`Abridor de cadera (moderno)`,description:`Clase contemporánea centrada en la cadera: estocadas y palomas a mitad de la práctica después del calentamiento, final yin-ish.`,focus:`Caderas`},"core-and-twist":{name:`Núcleo y torsión`,description:`Calor + núcleo + giros (tema popular de clase atlética), luego neutralizar los pliegues.`,focus:`Centro`},"inversion-prep":{name:`Preparación para la inversión`,description:`Preparación de hombros/isquiotibiales en inversiones con soporte: nunca omita el enfriamiento después de trabajar al revés.`,focus:`Inversiones`},"full-vinyasa-arc":{name:`Arco completo de Vinyasa (estilo 60)`,description:`Arco de clase condensado de 60 minutos de guías para profesores: centro → cálido → pararse → equilibrio máximo → caderas → savasana.`,focus:`cuerpo completo`},"gentle-floor":{name:`Flujo de piso suave`,description:`Día de recuperación en el suelo con peso ligero y equilibrio de pie.`,focus:`Cuerpo completo · gentil`},"sun-b-heat":{name:`Saludo al sol B Calor`,description:`Bloque de construcción clásico Sun B utilizado en Ashtanga/vinyasa: silla + ciclos Warrior I antes de trabajar de pie.`,focus:`Vinyasa · calor`},"peak-half-moon":{name:`Pico: Media Luna`,description:`Método de postura máxima de Yoga Journal para Ardha Chandrasana: preparación de triángulo/cuerpo lateral → equilibrio → aterrizaje suave.`,focus:`Pose máxima · equilibrio`},"peak-revolved-triangle":{name:`Pico: Triángulo Girado`,description:`Plantilla máxima para Parivrtta Trikonasana: tendón de la corva + girar los componentes por separado, luego combinar.`,focus:`Postura máxima · giro`},"shoulders-and-heart":{name:`Hombros y corazón abiertos`,description:`Secuenciación de partes del cuerpo (enfoque YJ): apertura gradual del hombro y extensión del corazón con contrapliegues.`,focus:`Hombros · pecho`},"grounding-root":{name:`Fuerza de puesta a tierra`,description:`Arco de clase de conexión a tierra moderna: formas pesadas de pie, equilibrio, luego caderas y savasana larga.`,focus:`De pie · puesta a tierra`},"desk-reset":{name:`Restablecimiento de escritorio (estilo 15)`,description:`Reinicio diario corto y popular: abridores de cuello/hombros/cadera sin un pico largo: un patrón de micropráctica compacto.`,focus:`Movilidad · breve`}},n=JSON.parse(`{"breath":{"title":"Respiración: cuándo y cómo","summary":"Haga coincidir el esfuerzo con la respiración: natural para recuperarse, firme para fortalecerse y nunca contenerse para seguir adelante.","body":"La respiración es el metrónomo de la práctica. Cuando la respiración es fácil, el sistema nervioso tiende a calmarse; cuando se detiene o se vuelve irregular, la postura suele ser demasiado intensa para hoy. Trate la respiración como información, no como algo que conquistar. Si necesita una regla para aplicar en cada tapete, hágala esta: mantenga la respiración continua y suavice la cara antes de profundizar en cualquier otra cosa.\\n\\nLa respiración natural significa una respiración suave por la nariz con un vientre y unas costillas tranquilos. Utilízalo en forma reconstituyente y yin, al inicio de la clase y siempre que te sientas apurado o autocrítico. No hay nada “menos yóguico” en una inhalación normal. El patrón de respiración libre de YogApp te deja en paz a propósito para que puedas encontrar tu propio ritmo sin seguir una señal.\\n\\nUna respiración constante o estilo ujjayi agrega una ligera constricción en la garganta que puede calentar y enfocar una secuencia de fuerza o de pie. Manténgalo suave: nunca fuerce el cuello ni fuerce un sonido fuerte del océano. Vincula el movimiento con la respiración de maneras sencillas: inhala para elevar, alargar o abrir; exhale para doblarse, girar o acomodarse. En los saludos al sol, esa combinación se convierte en un ritmo en el que puedes confiar incluso cuando la mente divaga.\\n\\nEvite contener la respiración para “impulsar” una postura difícil, la retención forzada en giros o inversiones y jadear por la boca cuando simplemente podría acortar la retención. Si la respiración se entrecorta, salga con control, descanse y regrese cuando pueda volver a hablar con oraciones completas. Habilite las señales de anuncio de respiración en Configuración si los recordatorios de inhalación y exhalación suaves lo ayudan a permanecer presente durante esperas más prolongadas."},"safety":{"title":"Seguridad y banderas rojas","summary":"La sensación de estiramiento o calor suele estar bien; Las señales agudas, eléctricas, mareadas o que cortan el aliento significan retroceder.","body":"Esta es una guía de práctica general, no un consejo médico: si tiene lesiones o afecciones, consulte a un maestro o médico calificado antes de adoptar nuevas formas.\\n\\nLa sensación de estiramiento, calor o cansancio muscular suele ser viable. Las señales agudas, eléctricas, mareadas o nauseabundas indican que debes retroceder. El dolor que te hace contener la respiración, apretar la mandíbula o perder la capacidad de abandonar la postura con control no es una señal de progreso. Salir temprano es habilidad. Descansar en la postura del niño o savasana todavía es una práctica.\\n\\nDeténgase o modifique si siente dolor agudo en las articulaciones, especialmente en rodillas, muñecas, cuello o espalda baja; entumecimiento u hormigueo que se intensifica; dolor punzante en una extremidad; mareo; cambios de visión; o dificultad para respirar más allá del esfuerzo normal. Si no puedes mantener una respiración constante, la intensidad es demasiado alta para este momento. Baja, respira y elige una forma más sencilla.\\n\\nLas zonas de precaución comunes merecen más paciencia. Para las muñecas en planchas y equilibrios de brazos, pruebe con los puños, los antebrazos u omita la postura. Para el cuello en posición de hombros, arado o camello profundo, nunca gire la cabeza; prefiera las piernas hacia arriba. Para las rodillas en loto, héroe o paloma profunda, no fuerces; Utilice una figura de cuatro o una variación compatible. Para la zona lumbar en flexiones profundas hacia atrás, acolche debajo de las caderas, doble las rodillas o permanezca en el puente.\\n\\nAbra cualquier pose en la biblioteca para evitar y modificar notas. Los accesorios no son un premio de consolación; son herramientas que mantienen las articulaciones espaciosas mientras desarrollas fuerza y ​​conciencia con el tiempo. En caso de duda, elige la versión que puedas repetir mañana sin miedo."},"sequencing":{"title":"Cómo se construyen las clases","summary":"La mayoría de las clases modernas siguen un arco de calentamiento, pico, contraposición y savasana que los profesores aprenden durante la formación.","body":"Una clase bien organizada se siente como una historia con un principio, un desarrollo y un final. Llegas, calientas el cuerpo, exploras un foco, neutralizas y descansas. Saltarse los sujetalibros (centrado y savasana) es como editar la primera y la última página de una novela: la mitad todavía ocurre, pero la integración no.\\n\\nLa mayoría de las clases modernas de vinyasa siguen un arco simple. Llegue y céntrese sentándose cómodamente, respirando y moviendo suavemente la columna. Calienta con gato-vaca, perro boca abajo y saludos al sol hasta que el aliento se despierte y las articulaciones se sientan aceitadas. El trabajo de pie y de pico introduce la postura de concentración con formas de preparación que enseñan sus partes (caderas, hombros, equilibrio o fuerza) sin dejarte caer primero en la versión más difícil.\\n\\nSiguen trabajos de piso y contraposturas: caderas, pliegues y giros que neutralizan el pico. Giros después de flexiones hacia atrás, pliegues suaves después de aperturas profundas de cadera y algo que permita que el sistema nervioso baje la velocidad. Savasana es integración, no una siesta opcional. Incluso tres minutos de tranquilidad ayudan a que la práctica se asiente en el cuerpo.\\n\\nCuando cree sus propias sesiones, pregunte qué necesita el pico. Un cuervo necesita muñecas cálidas, caderas abiertas y núcleo; una rueda necesita movilidad torácica y piernas fuertes; una retención prolongada del yin necesita un calor que ya sea lo suficientemente suave como para que puedas permanecer sin refuerzos. Las funciones integradas de YogApp siguen esta lógica (Sun A Foundation, Peak Warrior, Wheel, Crow, Yin, Restorative) y el asistente elige de ese menú usando la hora del día y su historial para que no tenga que reinventar el arco desde cero cada mañana."},"effort":{"title":"Cuando esforzarse más","summary":"Progrese una variable a la vez (rango, tiempo de espera o carga) y deje que la respiración constante sea la luz verde.","body":"No es lo mismo esforzarse en yoga que exprimirse al máximo en el gimnasio. La pregunta útil no es \\"¿Puedo forzar esto?\\" sino \\"¿Puedo ser amable y claro mientras exploro un poco más?\\" Progrese una variable a la vez: rango de movimiento, tiempo de espera o carga. Cambiar las tres cosas a la vez es cómo la forma colapsa y el resentimiento aparece.\\n\\nLas luces verdes que puedes profundizar incluyen una respiración constante, una cara y una mandíbula suaves, articulaciones que se sienten espaciosas en lugar de apretadas, una forma estable durante varias respiraciones y la capacidad de abandonar la postura con control. Si están presentes, puedes explorar media pulgada más, unos segundos más o una variación ligeramente más fuerte y luego volver a evaluar.\\n\\nLas luces amarillas y rojas indican que hay que bajar la velocidad. La respiración que se contiene o se vuelve irregular, los temblores que colapsan la alineación, el ego que impulsa la postura (“Debería poder…”), o el dolor agudo o neural son invitaciones a simplificar. Habrá otros días. La práctica que dura es la que te deja curioso en lugar de destrozado.\\n\\nDespués de una sesión, registre el esfuerzo en la pantalla de resumen cuando pueda. Los patrones importan más que cualquier hora heroica. El Mago usa tu historial para sugerir días más cortos después de los intervalos, lo cual es una gentil amabilidad hacia ti en el futuro. La fuerza crece tanto en la recuperación como en la espera; Trate los días de descanso como parte del entrenamiento, no como una falta de presentación."},"savasana-hardest":{"title":"Por qué savasana es la postura más difícil","summary":"Mentir todavía le pide a la mente que deje de actuar, y eso puede resultar más difícil que cualquier equilibrio o flexión hacia atrás.","body":"La gente se ríe cuando los profesores dicen que savasana es la postura más difícil y luego pasan los últimos minutos moviéndose, planeando la cena o mirando el reloj. El chiste surge porque es verdad. Después de cuarenta minutos de hacer, se le pide al sistema nervioso que deshaga, y deshacer no tiene marcador.\\n\\nEn asana podemos escondernos dentro del esfuerzo. La quemadura muscular se siente productiva. Un pliegue profundo parece un logro. Savasana no ofrece ningún lugar para realizar. Te acuestas, colocas las extremidades de manera que no sea necesario agarrar nada y te enfrentas a todo lo que te trae la mente: inquietud, aburrimiento, la necesidad de saltarte \\"sólo esta vez\\". Ese encuentro es la pose.\\n\\nDifícil no significa sombrío. Suaviza los ojos bajo los párpados cerrados. Deja descansar la lengua. Si llegan pensamientos, obsérvelos de la misma manera que nota las nubes: presentes, en movimiento, no es un problema que resolver en el tapete. Si necesita un puente hacia la quietud, primero adopte una postura infantil más larga o un giro reclinado con apoyo y luego acomódese. Tres minutos honestos superan a diez minutos de inquietud mientras finges que estás bien.\\n\\nSaltarse savasana para comenzar el día rápidamente le enseña al cuerpo que la práctica termina en urgencia. Mantenerlo, aunque sea brevemente, enseña que el esfuerzo tiene un lugar donde aterrizar. Si solo cambias un hábito este mes, protege el resto final. Deje su teléfono fuera de la sala y déle a la práctica la oportunidad de terminar de hablar."},"phones-off-mat":{"title":"Teléfonos fuera del tapete","summary":"Las notificaciones sacan la atención del cuerpo; un tapete sin teléfono es un pequeño límite con una calma enorme.","body":"Un teléfono sobre el tapete es una puerta que se deja abierta. Incluso boca abajo, bulle conversaciones inacabadas y la posibilidad de interrupción. El yoga ya exige suficiente (respiración, equilibrio, bondad) sin competir contra un rectángulo brillante que se nutre de la atención parcial.\\n\\nNo necesitas un monasterio. Pon el teléfono en otra habitación, o al menos en una bolsa con las notificaciones desactivadas. Si usa una aplicación para temporizadores o música, configúrela antes de comenzar y coloque el dispositivo donde no pueda ver la pantalla de bloqueo. Trate la sesión como una breve cita consigo mismo que otras personas pueden esperar.\\n\\nLa práctica en casa es especialmente vulnerable. El ping de la cocina, el Slack de trabajo, la necesidad de filmar una pose para más tarde. Cada mirada reinicia el sistema nervioso hacia la vigilancia. Las paredes del estudio ayudan porque el contrato social es más claro; en casa tienes que redactar ese contrato tú mismo. Un simple ritual ayuda: enrollar el tapete, silenciar el teléfono, respirar tres veces antes del primer movimiento.\\n\\nEsto no es un teatro de pureza. La vida está llena de razones legítimas para permanecer accesible. Es una votación a favor de la profundidad frente a la fragmentación durante veinte o cuarenta minutos. Cuando termine la práctica, los mensajes seguirán ahí. Podrías responderlas desde un lugar un poco más amplio, que es, en voz baja, el punto."},"beginner-ego":{"title":"El ego principiante y la trampa de la comparación","summary":"Querer “mantener el ritmo” es humano; confundir la forma de otra persona con tu tarea es la forma en que se escapa la alegría.","body":"Cada habitación tiene un sistema de clasificación silencioso si lo permites: quién se mantiene en equilibrio por más tiempo, quién toca el suelo con los talones, quién flota sin pensarlo dos veces. El ego principiante no es sólo vanidad: es el tierno deseo de pertenecer, mezclado con el miedo a ser visto como un atrasado. Esa combinación puede empujar a las personas a adoptar formas para las que sus articulaciones no están preparadas.\\n\\nLa comparación roba información. La parada de manos de su vecino no dice casi nada sobre sus muñecas, su sueño, su estrés o su década de trabajo de escritorio. Lo que parece sencillo pueden ser años de práctica, proporciones afortunadas o un cuerpo que aún no ha alcanzado sus límites. Tu trabajo no es igualar su silueta. Tu trabajo es notar tu respiración y elegir la versión que puedas salir con dignidad.\\n\\nLos profesores pueden alimentar accidentalmente la trampa al elogiar sólo la expresión más profunda. Las buenas habitaciones celebran las modificaciones en voz alta. Si eres nuevo, reclama el bloqueo, con la rodilla hacia abajo, el agarre más corto. Eso no es yoga menor; es yoga exacto. La precisión genera confianza, y la confianza es lo que le permite profundizar más adelante sin tener que afrontar la vergüenza.\\n\\nCuando el ego aumenta (“ya debería poder hacerlo”), haga una pausa y cambie el nombre del objetivo. El éxito de hoy podría ser quedarse con toda la clase, mantener el cuello suave en una flexión hacia atrás o irse antes de que llegue el dolor. El progreso a menudo se ve de lado: más facilidad en una pose familiar, menos prisa entre las formas, un narrador interior más amable. Esas victorias no se fotografían bien. Viajan bien."},"home-vs-studio":{"title":"Práctica en casa versus estudio","summary":"Los estudios ofrecen comunidad y estructura; el hogar ofrece flexibilidad: la mayoría de las prácticas duraderas toman prestado de ambos.","body":"La práctica en el estudio te entrega un contenedor: un tiempo, un maestro, otros cuerpos que respiran cerca. Ese contenedor hace que sea más fácil presentarse en los días en que la motivación es escasa. Pides prestada la secuencia, la música y el ritmo de otra persona y dejas la ropa sucia en otra habitación. Para muchas personas, esa estructura externa es la forma en que comienza un hábito.\\n\\nLa práctica en casa ofrece un regalo diferente. Puedes practicar al amanecer en pijama, acortar una sesión cuando la vida es ruidosa y explorar poses sin audiencia. También afrontas personalmente cada excusa: el correo electrónico, el refrigerio, la repentina necesidad de reorganizar un cajón. Sin un plan, la práctica en casa se disuelve en estiramientos mientras se piensa en el trabajo.\\n\\nUn enfoque duradero a menudo combina ambos. Utilice clases de estudio o en vivo para aprender a alinearse, descubrir nuevas secuencias y sentir el impulso del esfuerzo compartido. Utilice los días de casa para mantener la coherencia, incluso quince minutos concentrados, para que la práctica no dependa de un horario o un viaje diario. Escribe un pequeño ritual: el mismo rincón, las mismas tres primeras poses, el teléfono apartado, el cronómetro puesto.\\n\\nSi el hogar se siente solitario, agregue una estructura ligera con herramientas en las que confíe: una rutina familiar, señales de respiración o un breve pico que ya conozca. Si el estudio se siente performativo, elija salas de restauración o para principiantes y párese cerca de la parte de atrás hasta que el sistema nervioso se calme. Ninguno de los escenarios es moralmente superior. La pregunta es qué combinación te mantiene practicando con curiosidad en lugar de miedo."},"roots-of-asana":{"title":"Raíces de asana","summary":"El yoga clásico hacía hincapié en la quietud y la meditación; El vocabulario de asanas atléticas que muchos conocen es en gran medida moderno.","body":"Cuando la gente dice \\"yoga\\", a menudo se imagina una secuencia de posturas de pie, equilibrios y flujos. Esa imagen es reciente. Los textos clásicos como los Yoga Sutras mencionan las asanas principalmente como un asiento estable y cómodo para la meditación, una postura que apoya la quietud en lugar de un catálogo de formas atléticas. El cuerpo fue preparado para que la mente pudiera calmarse, no exhibido como el evento principal.\\n\\nLas tradiciones medievales de hatha ampliaron la práctica física: purificación, control de la respiración y posturas destinadas a estabilizar la energía para un trabajo más profundo. Incluso entonces, las listas de poses eran más pequeñas que el horario de un estudio moderno, y el objetivo seguía siendo la transformación de la atención y la vitalidad, no la quema de calorías ni las líneas de Instagram. El contexto importa: estas prácticas vivían dentro de linajes, votos y filosofías que rara vez encajan en una clase a la hora del almuerzo.\\n\\nEl siglo XX cambió el mapa. Los profesores de la India (entre ellos figuras asociadas con Mysore y linajes relacionados) sistematizaron asanas dinámicas, a menudo influenciadas por la gimnasia, la lucha libre y los ejercicios militares, así como por el hatha más antiguo. La fotografía, los manuales impresos y, más tarde, los viajes por todo el mundo llevaron esos sistemas al extranjero. Lo que muchos estudiantes occidentales heredaron fue un yoga postural vigoroso que todavía usaba nombres sánscritos y estructuras más antiguas, pero priorizaba la fuerza, la flexibilidad y el movimiento secuenciado.\\n\\nConocer esta historia no hace que su perro boca abajo sea menos real. Invita a la humildad. Asana puede ser devoción, terapia, deporte o meditación en movimiento dependiendo de cómo la realices. Cuando practicas hoy, te encuentras en una larga conversación: algunas páginas son antiguas, otras apenas tienen un siglo de antigüedad. Honra tanto el asiento como el sudor, y recuerda que la quietud era el destino original."},"hatha-vs-vinyasa":{"title":"Hatha vs vinyasa","summary":"Hatha a menudo significa posturas sostenidas y más lentas; vinyasa vincula la respiración con el movimiento; ambos pueden ser fuertes o suaves.","body":"En el marketing de estudio, \\"hatha\\" y \\"vinyasa\\" se utilizan como abreviaturas de lento versus fluido. Las palabras son más antiguas y más amplias que eso. Hatha históricamente señaló el camino físico y energético más amplio (posturas, respiración y prácticas relacionadas), no un solo estilo de clase. En un horario moderno, una clase de hatha generalmente implica posturas mantenidas durante varias respiraciones con más tiempo para la alineación y menos movimiento continuo.\\n\\nVinyasa, en su uso contemporáneo, enfatiza vincular la respiración con el movimiento y la transición entre formas. Los saludos al sol son el motor familiar. Las clases pueden ser deportivas o moderadas; el hilo conductor es el ritmo. Algunos linajes utilizan recuentos precisos; otros dejan el tiempo más abierto. De cualquier manera, el sistema nervioso tiende a permanecer más cálido y más móvil que en una habitación prolongada.\\n\\nNinguna etiqueta garantiza intensidad. Un “vinyasa suave” puede ser más suave que una exigente clase de hatha repleta de posiciones profundas y largos equilibrios. Lee la descripción, pregúntale al profesor y nota tu respiración después de diez minutos. Si necesita conexión a tierra, pueden resultar útiles las retenciones más prolongadas y menos transiciones. Si necesita deshacerse de la niebla mental, un flujo constante con vínculos claros entre la inhalación y la exhalación puede ser mejor.\\n\\nPara practicar en casa, puedes pedir prestados ambos. Caliente con un flujo corto y luego colóquelo en posición de pie o en el piso. O invierta: explore lentamente una postura máxima y luego use algunas transiciones relacionadas con la respiración para integrarse. La distinción útil no es la lealtad a la marca, sino si el cuerpo actual quiere ritmo, quietud o una conversación entre ambos."},"yin-origins":{"title":"De dónde viene el yin yoga","summary":"El largo piso de Yin se basa en ideas taoístas y enseñanzas modernas; complementa, en lugar de reemplazar, los estilos yang.","body":"El yin yoga, popularizado a finales del siglo XX, requiere que usted se acomode en formas durante minutos seguidos, generalmente en el suelo, con los músculos suaves en lugar de tensos para lucirse. El objetivo es tensar suavemente el tejido conectivo y darle al sistema nervioso una exhalación prolongada. Parece tranquilo desde fuera y puede resultar intensamente honesto por dentro.\\n\\nLos maestros asociados con el estilo se basaron en el lenguaje taoísta yin-yang y en ideas sobre vías fasciales y energéticas, tejiéndolas con formas de asanas familiares del hatha. Las afirmaciones históricas exactas varían según el maestro, y los académicos debaten cuán directamente se relaciona el yin moderno con las prácticas chinas más antiguas. Para los practicantes, el método vivido importa más que el folleto: llegar, encontrar un borde apropiado, quedarse, respirar y partir sin tirar.\\n\\nYin no es una competencia para sufrir más tiempo. Los accesorios, el acolchado y las salidas anticipadas son prudentes. El dolor agudo en las articulaciones sigue siendo una señal de alto. Debido a que las sujeciones son largas, se acumulan pequeñas desalineaciones: apoye las rodillas, mantenga el cuello relajado y elija variaciones que permitan que los músculos se derritan en lugar de agarrarse. El calor de antemano puede ayudar, pero muchas personas practican el yin fresco y aún así se benefician.\\n\\nPiense en el yin como un complemento de los estilos yang como vinyasa o clases de poder. Capacidad de generación de fuerza y ​​calor; Las mantenciones pasivas prolongadas enseñan paciencia y recuperación. Una semana que incluye ambos a menudo se siente más completa que duplicar solo la intensidad. Si su mente se acelera en quietud, acorte las pausas y mantenga el principio: menos esfuerzo muscular, más escucha."},"sanskrit-naming":{"title":"Nombres sánscritos en el tapete.","summary":"Los nombres de las poses llevan imágenes y linaje; aprender algunas raíces hace que la habitación se sienta menos como un código secreto.","body":"Los nombres de poses en sánscrito pueden parecer una pared si eres nuevo. Los maestros alternan entre “perro boca abajo” y adho mukha svanasana, y el cerebro se revuelve. Los nombres no están ahí para vigilar. Son imágenes compactas y marcadores de linaje: un mapa compartido que viaja a través de idiomas cuando las traducciones al inglés divergen.\\n\\nMuchos nombres se construyen a partir de piezas que puedes aprender como Lego. Adho significa hacia abajo; mukha significa cara; svana significa perro. Tri significa tres; kona significa ángulo, de ahí triángulo. Ardha significa mitad; chandra significa luna. Una vez que un puñado de raíces hacen clic, los nombres desconocidos dejan de ser ruido y comienzan a ser pistas sobre la forma y la dirección.\\n\\nNo necesitas fluidez para practicar bien. Las señales en inglés son suficientes para la seguridad y el aliento. Aún así, probar el sánscrito puede profundizar el respeto por la textura de la tradición, especialmente cuando un nombre apunta a un mito, animal o sabio. Di lo que puedas pronunciar amablemente; corrígete sin vergüenza. Los profesores difieren en cuanto al acento y las formas exactas: la coherencia dentro de un linaje importa más que ganar un concurso de pronunciación.\\n\\nSi la memorización te abruma, elige cinco posturas que te gusten y aprende ambos nombres. Úsalos en tu práctica en casa para que el sonido se una a la sensación. Con el paso de los meses, el glosario crece sin tarjetas didácticas. El objetivo no es impresionar la habitación. El objetivo es sentirse como en casa con un vocabulario que ha transmitido estas formas a lo largo de generaciones."},"eight-limbs":{"title":"Resumen de ocho miembros","summary":"Asana es una extremidad entre ocho: la ética, la respiración, los sentidos, la concentración y la meditación completan el mapa.","body":"El camino de ocho ramas de Patanjali es un mapa clásico que muchos profesores todavía hacen referencia. No exige que cada secuencia de guerreros en la clase de gimnasia se convierta en un seminario de filosofía. Nos recuerda que las posturas forman parte de un proyecto más amplio: cómo tratamos a los demás, cómo nos tratamos a nosotros mismos, cómo respiramos y cómo fijamos la atención.\\n\\nLas dos primeras ramas, yama y niyama, esbozan disciplinas éticas y personales: honestidad, no hacer daño, satisfacción y compromisos relacionados interpretados de manera diferente en todas las épocas. Asana, la tercera, es el asiento o postura encarnada. Pranayama trabaja con la respiración y la energía. Pratyahara vuelve los sentidos hacia adentro para que cada sonido y picazón tiren menos de la atención.\\n\\nLos tres últimos (dharana, dhyana y samadhi) describen la concentración, la meditación y la absorción profunda. Pocas clases modernas afirman poder entregar el último miembro en cuarenta y cinco minutos, y esa humildad es saludable. Lo que pueden ofrecer es práctica para regresar: notar la distracción, volver a respirar o sentir, repetir sin regañar.\\n\\nEn un martes práctico, las extremidades aparecen silenciosamente. Elegir no forzar una rodilla dolorida no es perjudicial. Aparecer cuando dijiste que lo harías es disciplina. Suavizar la mirada en equilibrio es una muestra de tranquilidad sensorial. No es necesario que domines la lista. Deje que se ensanche el marco para que la asana sea más que formas: un campo de entrenamiento para la atención y el cuidado que deja la estera con usted."},"modern-yoga-west":{"title":"Yoga moderno en Occidente","summary":"Los viajes, los libros y los estudios transformaron el yoga postural en una cultura de bienestar global con muchos dialectos.","body":"El yoga no llegó a Occidente como un solo paquete. Conferencias, libros, profesores visitantes y, posteriormente, la inmigración llevaron filosofías, prácticas respiratorias y sistemas posturales a Europa y América del Norte a lo largo del siglo XX. Algunas audiencias querían misticismo; otros querían salud, flexibilidad o calma. El mercado respondió con muchos dialectos bajo un nombre popular.\\n\\nA finales del siglo XX, los estudios de yoga, la formación de profesores y los medios de comunicación convirtieron las asanas en un estilo de vida reconocible. La cultura de la marca, la moda y el fitness amplificaron ciertos estilos vigorosos, mientras que las prácticas más tranquilas continuaron en salas más pequeñas. El éxito comercial trajo acceso y también distorsión: lenguaje espiritual utilizado como marketing, delgadez confundida con avance y linajes aplanados hasta convertirse en tendencias.\\n\\nLa crítica y la renovación crecieron junto con la popularidad. Los profesores y académicos formularon preguntas más difíciles sobre la apropiación cultural, la accesibilidad, las lesiones y quién se siente bienvenido en la sala. El lenguaje basado en el trauma, los espacios corporales positivos, el yoga en silla y las clases en línea ampliaron la puerta. Nada de eso borra el daño automáticamente (es un trabajo continuo), pero muestra que la tradición se está adaptando en público.\\n\\nPara un practicante actual, el “yoga occidental” es menos un veredicto que un paisaje. Puede buscar profundidad de linaje, atención terapéutica, desafío atlético o simple movimiento semanal. Elija maestros que citen fuentes honestamente, prioricen la seguridad y dejen espacio para preguntas. La historia global se sigue escribiendo cada vez que alguien desenrolla una alfombra con curiosidad en lugar de un disfraz."},"props-history":{"title":"Una breve historia de los accesorios.","summary":"Bloques, correas y mantas pasaron de ser soportes ingeniosos a herramientas estándar que hacen que las asanas sean más accesibles.","body":"Los accesorios parecen modernos (bloques de espuma de colores, correas de algodón, almohadones apilados como muebles), pero el impulso es antiguo: usar lo que ayude al cuerpo a encontrar una forma sostenible. Las cuerdas, las paredes y los objetos domésticos se han mantenido durante mucho tiempo cuando una postura requería longitud o apalancamiento que el cuerpo sin ayuda aún no podía ofrecer.\\n\\nEn el siglo XX, profesores como B.K.S. Iyengar hizo famoso el uso sistemático de accesorios: ladrillos, cinturones, sillas y mantas para refinar la alineación e incluir a los estudiantes que no podían aproximarse a una fotografía. Lo que algunas habitaciones alguna vez trataron como recuperación se convirtió, en ese enfoque, en diseño inteligente. La accesibilidad y la precisión compartían el mismo conjunto de herramientas.\\n\\nHoy en día, la mayoría de los estudios mantienen una pared de utilería sin disculpas. Un bloqueo debajo de la mano en triángulo no es una degradación; es una forma de mantener la columna larga mientras los isquiotibiales se recuperan. Una correa doblada hacia adelante enseña la forma de la postura sin doblarse y tensarse. Los refuerzos en la práctica restaurativa permiten que el sistema nervioso crea que es seguro descansar.\\n\\nSi el ego susurra que los accesorios son para principiantes, responde con longevidad. Las articulaciones prefieren la amplitud. La fuerza aún se construye cuando la base es honesta. Mantenga un bloque y una correa cerca del tapete de su casa de la misma manera que una cocina guarda una tabla de cortar: herramientas comunes para trabajar mejor. El movimiento avanzado es elegir el soporte que te permita respirar."}}`),r=JSON.parse(`{"calm-arrive":{"title":"Llegar y Establecerse","summary":"Aterrizaje suave al presente. Libera el día y encuentra tu asiento.","script":["Bienvenido.","Tómate un momento para llegar.","Busque un asiento cómodo o acuéstese si se siente mejor.","Deja que tus manos descansen.","Deja que tus ojos se cierren o suaviza tu mirada.","Fíjate que estás aquí.","No hay nada que arreglar ahora.","Nada que completar.","Respire lentamente por la nariz.","Y una exhalación más larga.","De nuevo. Inhala suavemente.","Exhala suavemente.","Siente el peso de tu cuerpo apoyado.","El suelo, la silla, la tierra que te sostiene.","Si los pensamientos divagan, está bien.","Simplemente observa y regresa a esta respiración.","Inhalar. Llegar.","Exhalar. Asentarse.","Un respiro más tranquilo.","Cuando estés listo, abre los ojos.","Lleva este silencio contigo."]},"body-scan":{"title":"Escaneo corporal","summary":"Atención suave desde la coronilla hasta los dedos de los pies. Aviso sin arreglar.","script":["Escanearemos suavemente el cuerpo.","Acuéstate o siéntate con facilidad.","Cierra los ojos si te sientes seguro.","Comience en la coronilla de la cabeza.","Note cualquier sensación allí. Calor. Frescura. Nada en absoluto.","No es necesario cambiarlo. Sólo fíjate.","Muévete suavemente hacia la frente y los ojos.","Deje que los pequeños músculos alrededor de los ojos se ablanden.","Siente la mandíbula. Afloja si puedes.","Lengua descansando ligeramente.","Espalda. ¿Están levantados? Déjalos caer un poco.","Brazos pesados. Manos abiertas o suaves.","El pecho sube y baja con la respiración.","Vientre suave. Sin forzar.","Caderas y pelvis en reposo.","Muslos. Rodillas. Piernas inferiores.","Pies. Suelas tocando el suelo o la colchoneta.","Ahora sienta todo el cuerpo como un campo de conciencia.","Respiración moviéndose a través de él.","Si aparece un punto tenso, envía una amable exhalación allí.","Quédese tres respiraciones tranquilas.","Cuando esté listo, mueva los dedos de las manos y los pies.","Abre los ojos. Regrese suavemente."]},"breath-awareness":{"title":"Conciencia de la respiración","summary":"Ancla a la respiración natural. Cuente ciclos suaves sin forzar.","script":["Adopte una postura estable.","Lomo alto pero no rígido.","Presta atención a la respiración tal como es.","No lo cambies todavía. Sólo mira.","Siente el frescor de la inhalación en las fosas nasales.","Siente el calor de la exhalación.","O observe el ascenso y descenso del vientre.","Elija un lugar para descansar su atención.","Cuando la mente divaga, por favor regresa.","Sin juicio. Sólo regresa.","Ahora, si te resulta fácil, cuenta los ciclos suaves.","Inhalar. Uno.","Exhalar. Uno.","Inhalar. Dos.","Exhalar. Dos.","Continúe hasta cinco, luego comience de nuevo en uno.","Si pierdes la cuenta, empieza de nuevo con amabilidad.","El regreso es la práctica.","Deja que la respiración sea natural. Sin tensión.","Unos ciclos más en silencio.","Liberar el conteo.","Descanse en conciencia abierta por un momento.","Cuando esté listo, abre los ojos."]},"loving-kindness":{"title":"Bondad amorosa Lite","summary":"Frases cortas de buena voluntad para ti y alguien que quieres.","script":["Siéntate cómodamente. Suaviza el rostro.","Coloque una mano sobre el corazón si eso ayuda.","Ofreceremos frases sencillas de bondad.","Primero, hacia ti mismo.","Repite en silencio conmigo o simplemente escucha.","¿Puedo estar a salvo?","Que esté bien.","Que pueda estar tranquilo.","Dígalas de nuevo, lentamente.","¿Puedo estar a salvo?","Que esté bien.","Que pueda estar tranquilo.","Si eso le resulta difícil, está bien. Quédate con el deseo mismo.","Ahora piense en alguien por quien sea fácil preocuparse.","Un amigo, una mascota, un amable extraño.","Imagínelos brevemente.","Que estés a salvo.","Que estés bien.","Que estés tranquilo.","Una vez más.","Que estés a salvo.","Que estés bien.","Que estés tranquilo.","Siente cualquier calidez que surja. O simplemente descansar en las palabras.","Vuelve a tu propia respiración.","Gracias a ti mismo por practicar.","Abre los ojos suavemente."]},"evening-wind-down":{"title":"Relajación nocturna","summary":"Libera el día. Ralentiza el sistema nervioso antes de dormir.","script":["Esta práctica es para el final del día.","Atenúa las luces si puedes.","Acuéstese o recuéstese con apoyo.","Deja que el día termine, incluso si la mente todavía enumera tareas.","Puedes dejarlos por ahora.","Inhale suavemente mientras cuenta hasta cuatro.","Exhala contando hasta seis.","De nuevo. Cuatro adentro. Seis afuera.","Las exhalaciones más largas le indican al cuerpo que es seguro descansar.","Busque restos de tensión en la cara.","Suaviza la frente. Suaviza la mandíbula.","Deja caer los hombros lejos de las orejas.","Imagínese el día asentándose como polvo después de una brisa.","Lo que pasó, pasó.","Lo que quede puede esperar hasta la mañana.","Siente el colchón o el suelo sosteniéndote.","Respira más tranquilo. Cuerpo más pesado.","Si llega el sueño, déjalo.","Si no, descansa de todos modos en esta suavidad.","Tres respiraciones lentas más.","En. Afuera.","En. Afuera.","En. Afuera.","Buenas noches al día. Paz a la noche."]},"anxiety-soft-landing":{"title":"Ansiedad aterrizaje suave","summary":"Tierra a través de los sentidos. Un breve reinicio cuando los nervios están a flor de piel.","script":["Si te sientes activado o preocupado, eres bienvenido aquí.","No es necesario que te sientas tranquilo todavía.","Sólo sígueme.","Si puedes, planta ambos pies en el suelo.","Siente el contacto. Tacones. Bolas de los pies. Dedos de los pies.","Presione hacia abajo suavemente. Observe el empuje hacia atrás desde el suelo.","Nombra cinco cosas que puedas ver.","En silencio. Sin prisas.","Nombra cuatro cosas que puedas tocar.","Ropa. Silla. Aire sobre la piel.","Nombra tres sonidos, cercanos o lejanos.","Nombra dos aromas o simplemente observa el aire.","Nombra un sabor o sensación en la boca.","Usted está aquí. En este cuerpo. En esta sala.","Ahora inhale por cuatro.","Mantenga suavemente durante dos.","Fuera por seis.","De nuevo si quieres.","Coloque una mano sobre el pecho o el vientre.","Siente el movimiento bajo tu mano.","Es posible que la ansiedad todavía esté presente. Eso está permitido.","Le has dado al sistema nervioso un aterrizaje más suave.","Toma un respiro más.","Cuando esté listo, abra los ojos y continúe con su día."]},"forest-clearing-5":{"title":"Tala de bosques","summary":"Llegue al cuerpo y luego descanse en un claro del bosque iluminado por el sol.","script":["Bienvenido.","Tome un asiento cómodo o acuéstese si se siente mejor.","Deja que tus manos descansen.","Deja que tus ojos se cierren o suaviza tu mirada.","Observe el peso de su cuerpo que se sostiene.","Respire lentamente por la nariz.","Y una exhalación más larga y más fácil.","De nuevo. Inhala suavemente.","Exhala suavemente.","Si los pensamientos divagan, está bien. Vuelve a la respiración.","Ahora, imagina un camino debajo de una hojarasca blanda.","Caminas sin prisas hacia un bosque tranquilo.","La luz moteada se mueve a través de tus antebrazos.","Siente el suave calor del sol dondequiera que toque tu piel.","Una frescura fresca transporta la brisa entre los árboles.","Huele a tierra verde, a corteza y a humedad mineral limpia.","El camino desemboca en un pequeño claro.","Moss amortigua un tronco caído. Te sientas.","La luz del sol se acumula en el centro como oro tranquilo.","Siente ese calor en tu rostro, lento y amable.","Una brisa toca tu cabello y refresca tus sienes.","El canto de los pájaros llega desde muy lejos y luego se desvanece.","Tu aliento coincide con el silencio de las hojas.","Inhala la frescura. Exhala cualquier resto de prisa.","Observe lo seguro que se siente el suelo debajo de usted.","Qué ancho parece el cielo sobre el dosel.","Un escarabajo cruza sin prisas un trozo de corteza iluminado por el sol.","No tienes dónde estar más que aquí.","El calor vuelve a acumularse en tus párpados cerrados.","El aire fresco se desliza bajo tu cuello como una mano amable.","Quédate con el calor en tus mejillas.","Quédese con el aire fresco en sus labios mientras exhala.","Este claro no pide nada. Simplemente te retiene.","Deje que una respiración más viaje hasta el vientre.","Y salir de nuevo, suave como las hojas.","Dirige tu atención lentamente por el borde del claro.","Helecho. Sombra. Un hongo pálido en la base de un tocón.","Todo es vívido porque no tienes prisa.","Vuelve a sentir el calor del sol donde cae sobre la rodilla.","Siente la brisa fresca donde se desliza por la garganta.","Podrías quedarte aquí toda la tarde. Por ahora, unas cuantas respiraciones son suficientes.","Ahora descansa un rato en la respiración a solas.","Inhala lentamente.","Exhala lentamente.","Inhalar.","Exhalar.","Siente calidez dondequiera que el cuerpo esté caliente.","Siente frescura dondequiera que el aire esté fresco.","Inhalar.","Exhalar.","Ningún lugar adonde ir. Nada que arreglar.","Inhalar.","Exhalar.","Descanse aquí durante unas cuantas respiraciones tranquilas.","Sepa que puede regresar a este lugar en cualquier momento.","Cuando estés listo, profundiza la respiración.","Mueve los dedos de las manos y de los pies.","Abre los ojos suavemente.","Lleva un poco de esta paz contigo."]},"lakeside-dawn-5":{"title":"Amanecer junto al lago","summary":"Respire con conciencia en una tranquila mañana de lago de calor y aire fresco.","script":["Bienvenido.","Tome un asiento cómodo o acuéstese si se siente mejor.","Deja que tus manos descansen.","Deja que tus ojos se cierren o suaviza tu mirada.","Observe el peso de su cuerpo que se sostiene.","Respire lentamente por la nariz.","Y una exhalación más larga y más fácil.","De nuevo. Inhala suavemente.","Exhala suavemente.","Si los pensamientos divagan, está bien. Vuelve a la respiración.","Imagínese al borde de un lago tranquilo al amanecer.","El agua sostiene un cielo plateado pálido.","El aire fresco roza tus mejillas con una frescura limpia.","Una suave cinta de sol comienza a calentar tus hombros.","Siente ese calor extendiéndose lentamente por tu espalda.","Te acercas. La arena suave cede bajo tus pies.","Sumerge las yemas de los dedos en el agua. Fresco. Claro.","Las ondas viajan hacia afuera y desaparecen.","La brisa huele levemente a plantas acuáticas y a la mañana.","Escuchar. Casi nada. Un pájaro lejano. Tu propio aliento.","Siéntese en una piedra lisa, calentada lo suficiente por la luz ascendente.","Siente el calor silencioso de la piedra debajo de ti.","Siente la frescura del aire entrando en tus pulmones.","El lago refleja un suave color rosa y dorado.","Ves la luz moverse por la superficie como una respiración lenta.","Un pez se eleva, los anillos se ensanchan y luego el espejo regresa.","Calor en tus párpados cerrados.","Frescor en el dorso de las manos.","A lo lejos, la cuerda de un barco hace ruido contra la madera.","Luego vuelve el silencio, amplio y amable.","Inhala la fresca mañana. Exhala hacia el agua abierta.","La paz calma la forma en que la niebla se levanta del agua: suave y completamente.","Se te permite ocupar espacio en este silencio.","Una degustación más del amanecer.","Mire de nuevo el camino plateado de luz sobre el agua.","Síguelo con ojos suaves hacia la otra orilla.","Los árboles de allí son azules por la distancia y la niebla de la mañana.","El calor crece un poco sobre tus hombros a medida que sale el sol.","La brisa se mantiene fresca, limpia y nacida del lago.","Deje que esa frescura enjuague la mente de la misma manera que la luz enjuaga la superficie.","Siéntense juntos durante tres respiraciones más de aire cálido y fresco.","Ahora descansa un rato en la respiración a solas.","Inhala lentamente.","Exhala lentamente.","Inhalar.","Exhalar.","Siente calidez dondequiera que el cuerpo esté caliente.","Siente frescura dondequiera que el aire esté fresco.","Inhalar.","Exhalar.","Ningún lugar adonde ir. Nada que arreglar.","Inhalar.","Exhalar.","Descanse aquí durante unas cuantas respiraciones tranquilas.","Sepa que puede regresar a este lugar en cualquier momento.","Cuando estés listo, profundiza la respiración.","Mueve los dedos de las manos y de los pies.","Abre los ojos suavemente.","Lleva un poco de esta paz contigo."]},"meadow-breeze-5":{"title":"pradera de montaña","summary":"Acomódese y luego recuéstese sobre la cálida hierba bajo una suave brisa alpina.","script":["Bienvenido.","Tome un asiento cómodo o acuéstese si se siente mejor.","Deja que tus manos descansen.","Deja que tus ojos se cierren o suaviza tu mirada.","Observe el peso de su cuerpo que se sostiene.","Respire lentamente por la nariz.","Y una exhalación más larga y más fácil.","De nuevo. Inhala suavemente.","Exhala suavemente.","Si los pensamientos divagan, está bien. Vuelve a la respiración.","Imagínese una amplia pradera de montaña al final de la mañana.","Los pastos altos se mecen en suaves olas.","El sol calienta sin ser fuerte.","Siéntelo en la coronilla de tu cabeza, amable y firme.","Una brisa fresca se mueve entre la hierba y encuentra tu rostro.","Huele a flores silvestres y a tierra secada al sol.","Caminas lentamente, rozando las cabezas de las semillas con las yemas de los dedos.","Cosquillas suaves. Sonido suave.","Las mariposas se elevan y se posan nuevamente, sin prisas.","Encuentra un lugar para recostarse en la hierba.","La tierra sostiene toda tu longitud.","Calidez a lo largo de tu frente. Sombra de tierra fresca a tus lados.","La brisa va y viene como una marea amiga.","Inhala frescura. Exhala hacia el cielo abierto.","Una nube se desliza por el sol por un momento.","Frescura. Luego el calor regresa a tu rostro.","Observe cuán grande se siente el silencio.","Qué pequeña parece cualquier preocupación en este amplio campo.","Tus manos descansan en la hierba. Los tallos diminutos se presionan amablemente.","Quédate con el calor del sol en tus ojos cerrados.","Quédate con la suave presión del césped contra tus brazos.","Se te permite estar así de quieto.","Deja que la pradera te respire durante unos ciclos más.","Desvía tu atención desde la cálida coronilla de la cabeza.","A través de un rostro suave, una garganta suave,","en un cofre que se eleva fácilmente a cielo abierto.","La brisa encuentra el interior de tus muñecas.","Fresco. Vivo. Amigable.","En algún lugar las abejas trabajan sin urgencia.","Su zumbido es otro tipo de silencio.","Quédese hasta que la calidez y la frescura se sientan como una sola tela.","Ahora descansa un rato en la respiración a solas.","Inhala lentamente.","Exhala lentamente.","Inhalar.","Exhalar.","Siente calidez dondequiera que el cuerpo esté caliente.","Siente frescura dondequiera que el aire esté fresco.","Inhalar.","Exhalar.","Ningún lugar adonde ir. Nada que arreglar.","Inhalar.","Exhalar.","Descanse aquí durante unas cuantas respiraciones tranquilas.","Sepa que puede regresar a este lugar en cualquier momento.","Cuando estés listo, profundiza la respiración.","Mueve los dedos de las manos y de los pies.","Abre los ojos suavemente.","Lleva un poco de esta paz contigo."]},"cove-shore-5":{"title":"Cala protegida","summary":"Cuerpo y respiración, luego una tranquila cala de playa de sol y aire salado.","script":["Bienvenido.","Tome un asiento cómodo o acuéstese si se siente mejor.","Deja que tus manos descansen.","Deja que tus ojos se cierren o suaviza tu mirada.","Observe el peso de su cuerpo que se sostiene.","Respire lentamente por la nariz.","Y una exhalación más larga y más fácil.","De nuevo. Inhala suavemente.","Exhala suavemente.","Si los pensamientos divagan, está bien. Vuelve a la respiración.","Imagínese llegar a una cala protegida.","Los acantilados se curvan alrededor de arena suave y pálida.","El mar se mueve en olas bajas y pacientes.","Un sol suave calienta la parte superior de tus hombros.","Una brisa salada refresca tus labios y párpados.","Siente la frescura de ese aire llenando tu pecho.","Camine hasta la línea de flotación. La arena mojada abraza tus pies.","La espuma fría toca tus tobillos y se desliza.","El ritmo es simple. Llegar. Ablandar. Dejar.","Siéntate donde la arena seca esté cálida debajo de ti.","Recuéstate sobre tus manos. Siente el calor granulado.","Escuche el silencio y el bullicio de la cala.","Huele a sal, a sol y a piedra limpia.","Calidez en tu piel. Frescor en cada inhalación.","A lo lejos, la luz brilla como una risa silenciosa.","No es necesario que lo persigas. Ya está aquí.","Una ola llega más lejos, refresca los dedos de los pies y luego retrocede.","La arena cálida recupera tus pies.","Deje que su respiración se mueva con las olas: inhalando lentamente, exhalando más tiempo.","La paz es la cala misma. Estás dentro de él.","Descanse su atención en el calor entre sus omóplatos.","Y en el aire fresco y salado en la punta de la nariz.","Traza la línea del acantilado con suave imaginación.","Piedra calentada durante el día. Sombra fresca en los pliegues.","Una piscina de marea cercana contiene un pequeño mundo claro.","No es necesario que te inclines. Saber que está ahí es suficiente.","Otra ola. Tobillos frescos. Arena cálida. Aliento suave.","La cala sigue ofreciendo la misma amabilidad sencilla.","Recíbelo una vez más antes de partir.","Ahora descansa un rato en la respiración a solas.","Inhala lentamente.","Exhala lentamente.","Inhalar.","Exhalar.","Siente calidez dondequiera que el cuerpo esté caliente.","Siente frescura dondequiera que el aire esté fresco.","Inhalar.","Exhalar.","Ningún lugar adonde ir. Nada que arreglar.","Inhalar.","Exhalar.","Descanse aquí durante unas cuantas respiraciones tranquilas.","Sepa que puede regresar a este lugar en cualquier momento.","Cuando estés listo, profundiza la respiración.","Mueve los dedos de las manos y de los pies.","Abre los ojos suavemente.","Lleva un poco de esta paz contigo."]},"garden-dusk-5":{"title":"Jardín al anochecer","summary":"Suave llegada a un jardín vallado para refrescarse de un día cálido.","script":["Bienvenido.","Tome un asiento cómodo o acuéstese si se siente mejor.","Deja que tus manos descansen.","Deja que tus ojos se cierren o suaviza tu mirada.","Observe el peso de su cuerpo que se sostiene.","Respire lentamente por la nariz.","Y una exhalación más larga y más fácil.","De nuevo. Inhala suavemente.","Exhala suavemente.","Si los pensamientos divagan, está bien. Vuelve a la respiración.","Imagínese un tranquilo jardín amurallado al suave atardecer.","Los caminos de piedra retienen el último calor del día.","Siente ese suave calor a través de las plantas de tus pies.","La lavanda y las rosas vespertinas liberan una fragancia tranquila.","Una brisa fresca se desliza por la pared y refresca tu cuello.","El aire es fresco después de una tarde cálida.","Caminas lentamente entre setos recortados suaves como el aliento.","Tus dedos rozan las hojas que aún sostienen el sol.","Cálido. Liso. Vivo.","Un banco de madera espera debajo de un árbol tranquilo.","Te sientas. La madera resulta agradablemente cálida en la espalda.","Arriba, el cielo se vuelve lavanda y rosa.","Los pájaros se posan. El jardín se vuelve silencioso.","Siente la calidez que se desvanece amablemente en la piedra y la madera.","Siente el frescor de la noche en tu rostro.","Inhala aroma y quietud.","Exhala el día que entraste.","Una polilla atraviesa la última luz dorada.","Aquí nada es urgente. Todo es suficiente.","Descansa en esa suficiente.","Deja que tu vientre se ablande con el aire del atardecer.","Deja que tu próximo aliento sea el más tranquilo del día.","Camine un bucle lento por el sendero antes de terminar.","Piedras cálidas que se enfrían bajo los pies.","Los setos liberan el perfume almacenado del día.","La brisa ahora tiene un toque vespertino: fresca, casi dulce.","Haz una pausa en la puerta sin abrirla todavía.","Siente cómo la calma se ha instalado en tus hombros.","Lleva el silencio del jardín como una pequeña linterna hacia el interior.","Ahora descansa un rato en la respiración a solas.","Inhala lentamente.","Exhala lentamente.","Inhalar.","Exhalar.","Siente calidez dondequiera que el cuerpo esté caliente.","Siente frescura dondequiera que el aire esté fresco.","Inhalar.","Exhalar.","Ningún lugar adonde ir. Nada que arreglar.","Inhalar.","Exhalar.","Descanse aquí durante unas cuantas respiraciones tranquilas.","Sepa que puede regresar a este lugar en cualquier momento.","Cuando estés listo, profundiza la respiración.","Mueve los dedos de las manos y de los pies.","Abre los ojos suavemente.","Lleva un poco de esta paz contigo."]},"forest-path-10":{"title":"Camino del bosque profundo","summary":"Viaje más largo a través de un viejo bosque hacia el musgo, el arroyo y la quietud.","script":["Bienvenido.","Encuentra una postura que no te pida nada.","Siéntate o acuéstate con el apoyo que necesites.","Deja que tus manos descansen abiertas o suaves.","Deje que sus ojos se cierren o mantenga una mirada suave.","Siente los lugares donde tu cuerpo se encuentra con el suelo.","Los talones, los isquiones, la parte posterior de la cabeza o la longitud de la columna.","No hay nada que retrasar ahora.","Respire lentamente por la nariz.","Siente el frescor del aire llegando.","Y exhale un poco más.","Siente el calor de la exhalación al irse.","De nuevo. Inhala suavemente.","Exhala sin prisas.","Deja que los hombros caigan una fracción.","Deja que la mandíbula se afloje.","Deja que la barriga esté suave.","Quédate con tres respiraciones tranquilas, tal como están.","Inhalar. Llegar.","Exhalar. Asentarse.","Si la mente divaga, obsérvalo con amabilidad y regresa a esta respiración.","Ahora comience una caminata lenta hacia un bosque viejo.","El camino está suave con agujas y hojas caídas.","Cada paso produce un sonido suave, luego regresa el silencio.","La luz del sol se filtra a través de las ramas altas en cálidas cintas.","Siente una mancha de sol en tu antebrazo: un calor suave y repentino.","Luego sombree nuevamente, fresco y verde.","Una brisa mueve el dosel. El aire fresco encuentra tu rostro.","Huele a resina, a tierra húmeda y a la limpia dulzura del musgo.","Pausa. Coloque una palma sobre la corteza rugosa.","Siente la quietud del árbol entrar en tu mano.","Continúe más profundamente. Los sonidos del mundo exterior se desvanecen.","En algún lugar, un arroyo habla con pequeñas sílabas brillantes.","Se sigue hasta que aparece agua entre las piedras.","Arrodillarse. Sumerge tus manos. Genial claridad.","Salpica un poco en tus muñecas. El frescor despierta la piel.","Siéntate en una roca plana calentada por una estrecha columna de sol.","Siente ese calor en los isquiones y en la parte posterior de los muslos.","Siente el aliento fresco del arroyo contra tus espinillas.","Los pájaros cantan una vez y luego abandonan el silencio nuevamente.","Respire la frescura del bosque.","Exhale hacia los troncos de pacientes que lo rodean.","Observa cómo tus hombros han caído sin que te lo pidan.","Cómo se ablanda la mandíbula cuando no hay otro lugar donde estar.","Ponte de pie cuando estés listo y camina un poco más.","Los helechos rozan tus pantorrillas con las frescas y verdes yemas de tus dedos.","Se abre un claro, redondo como un suspiro contenido.","Recuéstese sobre musgo profundo.","La tierra recibe tu peso por completo.","Calor del sol filtrado en tu rostro.","Frescura del musgo a lo largo de tu columna.","La brisa llega, se va, vuelve a llegar.","Quédate con la sensación de estar sostenido por un lugar vivo.","Seguro. Tranquilo. Pertenecer sin esfuerzo.","Cuente cinco respiraciones lentas aquí, cada una más suave.","Note el olor nuevamente: verde, húmedo, honesto.","Observe el sonido nuevamente: casi ninguno, y eso es suficiente.","Si aparece un pensamiento, déjalo flotar como una hoja en la corriente.","Vuelve al calor en la piel allí donde te encuentre el sol.","Vuelve al frescor a la sombra entre esas cintas cálidas.","Has caminado lo suficiente hacia adentro.","Deja que tres respiraciones lentas sellen esto en el cuerpo.","Antes de partir, párese una vez más junto al arroyo.","Observe cómo el agua clara se trenza alrededor de las piedras.","El aire frío se eleva desde la superficie en movimiento.","La luz cálida todavía llega a una franja de tu antebrazo.","Taza de agua y humedece la frente si lo deseas: en la imaginación, fresca y amable.","El bosque no aplaude. Simplemente continúa.","Esa continuidad es un maestro.","Camine por el camino hacia afuera con unos pocos pasos silenciosos en la mente.","Agujas bajo los pies. Sonido suave. Regreso suave.","Sin embargo, la paz del claro permanece en el cofre como el sol almacenado.","Siéntelo allí: calidez detrás del esternón.","Siente el frescor aún en las fosas nasales.","Puedes llevar ambos a habitaciones normales.","Una última mirada a través de las ramas hacia una moneda de cielo.","Suficiente.","Ahora deja descansar la historia y quédate con las sensaciones.","Inhala la frescura de este lugar.","Exhala hacia su calidez y tranquilidad.","Inhalar.","Exhalar.","De nuevo. Inhala suavemente.","Exhalación más larga.","Siente el cuerpo sostenido por el suelo de este mundo imaginado.","Inhalar.","Exhalar.","Si los pensamientos divagan, regrese al calor de la piel.","O para enfriar el aire en la nariz.","Inhalar.","Exhalar.","Inhalar.","Exhalar.","Permanecer. Ablandar. Continuar.","Inhalar.","Exhalar.","Un ciclo más fácil.","Inhalar.","Exhalar.","Permanece en este sentimiento durante unas cuantas respiraciones más.","Calor. Blandura. Suficiente.","Puedes regresar a este lugar cuando lo necesites.","Vive en tu atención, no sólo en tu imaginación.","Comience a profundizar la respiración.","Vuelve a sentir la habitación que te rodea.","Mueve los dedos. Suaviza los dedos de los pies.","Cuando estés listo, abre los ojos.","Respira tranquilamente una vez más.","Lleva esta calma a lo que venga después."]},"lake-wander-10":{"title":"Paseo por la orilla del lago","summary":"Un completo paseo junto al lago de piedras cálidas, agua fresca y cielo abierto.","script":["Bienvenido.","Encuentra una postura que no te pida nada.","Siéntate o acuéstate con el apoyo que necesites.","Deja que tus manos descansen abiertas o suaves.","Deje que sus ojos se cierren o mantenga una mirada suave.","Siente los lugares donde tu cuerpo se encuentra con el suelo.","Los talones, los isquiones, la parte posterior de la cabeza o la longitud de la columna.","No hay nada que retrasar ahora.","Respire lentamente por la nariz.","Siente el frescor del aire llegando.","Y exhale un poco más.","Siente el calor de la exhalación al irse.","De nuevo. Inhala suavemente.","Exhala sin prisas.","Deja que los hombros caigan una fracción.","Deja que la mandíbula se afloje.","Deja que la barriga esté suave.","Quédate con tres respiraciones tranquilas, tal como están.","Inhalar. Llegar.","Exhalar. Asentarse.","Si la mente divaga, obsérvalo con amabilidad y regresa a esta respiración.","Imagínese despertarse junto a un lago amplio y tranquilo.","La luz de la mañana cae suave sobre el agua.","El aire fresco toca tus mejillas con una frescura limpia.","El primer sol calienta la parte superior de tus pies.","Comienzas un lento paseo por la orilla.","La arena y las pequeñas piedras lisas se mueven suavemente bajo los pies.","Cada paso es una conversación tranquila con el suelo.","Una brisa sale del agua: fresca, ligeramente fresca.","Levanta el cabello en las sienes.","Huele a cedro, a piedras mojadas y a mañana abierta.","Observa una garza parada en aguas poco profundas, perfectamente quieta.","Igualas esa quietud durante unas cuantas respiraciones.","El calor crece sobre tus hombros a medida que sale el sol.","Encuentra una roca iluminada por el sol y siéntate.","Siente el calor almacenado en la piedra ascendiendo hacia tu cuerpo.","Siente el aire más fresco moverse por tus labios con cada inhalación.","La superficie del lago se arruga y luego vuelve a ser de cristal.","La luz tiembla allí como una alegría silenciosa.","Continúe por una curva de la costa hacia una pequeña bahía.","Las cañas susurran. El agua golpea suavemente la madera.","Se extiende un antiguo muelle. Caminas hasta el final.","Siéntate con los pies colgando sobre el agua fría.","Sol en tu espalda. Brisa en tus espinillas.","Sumerge un dedo del pie. Frío suave. Una sonrisa que no necesitas mostrar.","Recuéstese sobre las cálidas tablas.","Escuche el agua debajo de usted. Cielo sobre ti.","Tu respiración se vuelve tan amplia como el lago.","Inhala frescura. Exhala hacia un azul infinito.","Nada que solucionar. Sólo este calor, este aire, esta paz.","Siente el calor del muelle a lo largo de tu columna.","Siente una franja de aire más fresco cada vez que cambia la brisa.","Una libélula sutura el aire y desaparece.","Quédese hasta que la sensación penetre en los músculos y los huesos.","Si la mente enumera tareas, déjelas en la orilla lejana por ahora.","Pueden esperar. El lago no espera nada.","Una mano en el vientre. Elevar. Caer.","Calor bajo la palma de la otra mano sobre la madera.","Descanse en esta doble sujeción: cuerpo y lugar.","Párese y camine un poco más lejos en la imaginación.","Los guijarros chasquean suavemente. El agua se ilumina cerca de una rama caída.","El sol encuentra la nuca con un calor amigable.","La sombra de un sauce refresca tus párpados durante unos pocos pasos.","Alternar calidez y frescura se convierte en una oración andante.","No se requieren palabras. Sólo sensación y respiración.","Busque un trozo de arena cálida y siéntese frente al mar abierto.","Deja que los ojos se suavicen en la línea del horizonte.","Inhala el fresco perfume del lago.","Exhala hacia las colinas distantes.","Todo lo que llevaste aquí puede descansar en la orilla a tu lado.","No es necesario llevarlo en el agua.","Quédese hasta que las siguientes tres respiraciones se sientan completas por sí solas.","Ahora deja descansar la historia y quédate con las sensaciones.","Inhala la frescura de este lugar.","Exhala hacia su calidez y tranquilidad.","Inhalar.","Exhalar.","De nuevo. Inhala suavemente.","Exhalación más larga.","Siente el cuerpo sostenido por el suelo de este mundo imaginado.","Inhalar.","Exhalar.","Si los pensamientos divagan, regrese al calor de la piel.","O para enfriar el aire en la nariz.","Inhalar.","Exhalar.","Inhalar.","Exhalar.","Permanecer. Ablandar. Continuar.","Inhalar.","Exhalar.","Un ciclo más fácil.","Inhalar.","Exhalar.","Permanece en este sentimiento durante unas cuantas respiraciones más.","Calor. Blandura. Suficiente.","Puedes regresar a este lugar cuando lo necesites.","Vive en tu atención, no sólo en tu imaginación.","Comience a profundizar la respiración.","Vuelve a sentir la habitación que te rodea.","Mueve los dedos. Suaviza los dedos de los pies.","Cuando estés listo, abre los ojos.","Respira tranquilamente una vez más.","Lleva esta calma a lo que venga después."]},"coastal-walk-10":{"title":"Camino Costero","summary":"Camino del acantilado a la playa: sol, brisa salada y aliento al ritmo de la marea.","script":["Bienvenido.","Encuentra una postura que no te pida nada.","Siéntate o acuéstate con el apoyo que necesites.","Deja que tus manos descansen abiertas o suaves.","Deje que sus ojos se cierren o mantenga una mirada suave.","Siente los lugares donde tu cuerpo se encuentra con el suelo.","Los talones, los isquiones, la parte posterior de la cabeza o la longitud de la columna.","No hay nada que retrasar ahora.","Respire lentamente por la nariz.","Siente el frescor del aire llegando.","Y exhale un poco más.","Siente el calor de la exhalación al irse.","De nuevo. Inhala suavemente.","Exhala sin prisas.","Deja que los hombros caigan una fracción.","Deja que la mandíbula se afloje.","Deja que la barriga esté suave.","Quédate con tres respiraciones tranquilas, tal como están.","Inhalar. Llegar.","Exhalar. Asentarse.","Si la mente divaga, obsérvalo con amabilidad y regresa a esta respiración.","Vea un sendero costero a lo largo de acantilados bajos.","El océano respira abajo en movimientos largos y constantes.","La luz del sol calienta la coronilla y el puente de la nariz.","Una brisa salada refresca tus párpados con un frescor luminoso.","Huele el mar: mineral, limpio, despierto.","Caminas despacio. Los pastos se inclinan hacia el interior con el viento.","Siente el sol en una mejilla y el aire fresco en la otra.","Ese contraste es en sí mismo una especie de calma.","Una escalera de madera conduce a una playa escondida.","Cada paso es seguro. Tu mano descansa sobre un riel desgastado.","Madera cálida bajo la palma de tu mano.","En el fondo, la arena recibe tus pies como un suave sí.","Camine hasta donde las olas escriben y borran líneas blancas.","El agua fría se pliega sobre tus tobillos.","La arena cálida en lo alto de la orilla espera cuando das un paso atrás.","Sentarse. Introduce tus manos en los granos calentados por el sol.","Siente ese calor seco contra la arena fresca y húmeda debajo.","Observe cómo la luz se hace añicos en aguas abiertas.","Respira la frescura de la brisa.","Exhale cualquier tensión que aún tenga las costillas.","Una gaviota llora una vez y se convierte en parte del silencio.","Recostarse. Cierra los ojos.","Calidez en tu frente. Fresca sombra de tierra a tus costados.","El ritmo de la marea guía tu corazón hacia la tranquilidad.","Eres pequeño en el mejor sentido: sostenido por algo vasto y amable.","Quédate con el calor del sol en tus ojos cerrados.","Quédate con el beso fresco del spray en tu piel cuando cambie el viento.","La paz no está en otra parte. Es esta orilla, este aliento, este cuerpo.","Clava los talones un poco más en la arena tibia.","Siente cómo la tierra responde con un apoyo constante.","Inhale la frescura de la sal hasta el fondo de los pulmones.","Exhale todo lo que se haya estado preparando para el impacto.","Aquí no hay ningún impacto. Sólo llegada tras llegada de olas.","Deje que cinco respiraciones sigan ese mismo ritmo paciente.","Luego descansa bajo el resplandor del sol sobre la piel.","Levántese y camine un corto trecho por la línea de flotación.","Pie izquierdo fresco y mojado. Pie derecho cálido y seco. Entonces cambia.","El cuerpo aprende el contraste como consuelo, no como conflicto.","Recoge una piedra lisa calentada por la luz.","Siente su calor en la palma. Su densidad. Es tranquilo.","Déjelo a un lado con agradecimiento; no es necesario que lo guarde.","La guarda es hacia adentro.","Mire más allá de las olas para ver colores más tranquilos.","Respira como si pudieras sentir el sabor azul.","Brisa fresca. Mejilla cálida. Vientre blando.","Deja que la siguiente inhalación sea la más profunda de la práctica.","Deja que la exhalación se vacíe sin fuerza.","La cala, el acantilado, el camino a casa... todo espera sin presión.","Ahora deja descansar la historia y quédate con las sensaciones.","Inhala la frescura de este lugar.","Exhala hacia su calidez y tranquilidad.","Inhalar.","Exhalar.","De nuevo. Inhala suavemente.","Exhalación más larga.","Siente el cuerpo sostenido por el suelo de este mundo imaginado.","Inhalar.","Exhalar.","Si los pensamientos divagan, regrese al calor de la piel.","O para enfriar el aire en la nariz.","Inhalar.","Exhalar.","Inhalar.","Exhalar.","Permanecer. Ablandar. Continuar.","Inhalar.","Exhalar.","Un ciclo más fácil.","Inhalar.","Exhalar.","Permanece en este sentimiento durante unas cuantas respiraciones más.","Calor. Blandura. Suficiente.","Puedes regresar a este lugar cuando lo necesites.","Vive en tu atención, no sólo en tu imaginación.","Comience a profundizar la respiración.","Vuelve a sentir la habitación que te rodea.","Mueve los dedos. Suaviza los dedos de los pies.","Cuando estés listo, abre los ojos.","Respira tranquilamente una vez más.","Lleva esta calma a lo que venga después."]},"canyon-gold-10":{"title":"Cañón Dorado","summary":"Piedra cálida y aire fresco del cañón bajo la luz dorada del atardecer.","script":["Bienvenido.","Encuentra una postura que no te pida nada.","Siéntate o acuéstate con el apoyo que necesites.","Deja que tus manos descansen abiertas o suaves.","Deje que sus ojos se cierren o mantenga una mirada suave.","Siente los lugares donde tu cuerpo se encuentra con el suelo.","Los talones, los isquiones, la parte posterior de la cabeza o la longitud de la columna.","No hay nada que retrasar ahora.","Respire lentamente por la nariz.","Siente el frescor del aire llegando.","Y exhale un poco más.","Siente el calor de la exhalación al irse.","De nuevo. Inhala suavemente.","Exhala sin prisas.","Deja que los hombros caigan una fracción.","Deja que la mandíbula se afloje.","Deja que la barriga esté suave.","Quédate con tres respiraciones tranquilas, tal como están.","Inhalar. Llegar.","Exhalar. Asentarse.","Si la mente divaga, obsérvalo con amabilidad y regresa a esta respiración.","Imagínese un amplio cañón pintado en suave oro y rosa.","Ya es última hora de la tarde. La luz es generosa.","El calor irradia la piedra que ha retenido el sol durante todo el día.","Siente ese calor radiante en tus espinillas y el dorso de tus manos.","Una brisa fresca y seca recorre el fondo del cañón.","Refresca tu rostro sin quitarte la comodidad del calor.","Caminas por un sendero arenoso entre paredes tranquilas.","Los pasos susurran. Los ecos son suaves, casi educados.","Huele a tierra quemada por el sol, a salvia y a polvo limpio.","Coloque su palma sobre una piedra lisa.","Siente la luz del día almacenada allí: calor constante y paciente.","Una cinta de sombra ofrece frescor durante unos pocos pasos.","Luego, de nuevo el sol, cálido sobre los hombros como un chal.","Llegas a un lugar donde se abre el cañón.","Siéntate en una roca plana que todavía conserva el calor dorado.","Sienta cómo se eleva a través de su asiento y su columna vertebral.","Siente el aire más fresco de la altitud en cada inhalación.","Muy arriba, un halcón gira lentamente en círculos sin prisa.","Tomas prestada esa cualidad sin prisas.","Respira profundamente. Cuerpo pesado. Mente amplia como el cielo entre paredes.","Observa cómo la sombra sube por el lejano acantilado mientras se pone el sol.","Los colores se intensifican. El calor se suaviza pero no desaparece.","La brisa ahora huele más fresca, fresca del atardecer.","Rodéate con tus brazos por un momento.","Calidez de tu propio cuerpo. Calor de piedra. Suficiente.","Recuéstese con cuidado y observe la primera estrella silenciosa.","El cañón te sostiene de la misma manera que una mano ahuecada sostiene el agua: suavemente, sin derramarse.","Descansa en ese sentimiento retenido.","Observe el último calor que se eleva desde la roca hacia el aire frío.","Observe cómo la brisa ahora huele a tarde, a polvo y a salvia.","Tu respiración se ha ralentizado para adaptarse al amplio silencio.","Si la tensión persiste en la frente, suavicela con esta luz dorada.","Si la mandíbula está apretada, déjela colgar mientras el halcón gira con facilidad.","Quédese unos cuantos ciclos más de piedra caliente y aire fresco.","No llegas tarde. Usted está aquí.","Camine unos pasos más sobre arena cálida entre las paredes del cañón.","Tu sombra se extiende larga y despreocupada.","Coloque nuevamente ambas palmas sobre la piedra.","El calor llega a las manos como una bendición que no tienes que ganarte.","La brisa peina el frescor por tu cabello.","Aroma de salvia. Olor a polvo. Aroma de sol.","Sentarse. Rodillas suaves. Lomo fácil.","Observe cómo el color se intensifica desde el dorado hasta el rosa.","El calor se suaviza. Aumenta la frescura. El equilibrio permanece.","Así es como las tardes le enseñan al sistema nervioso a reducir la marcha.","Toma prestada la lección sin esfuerzo.","Tres respiraciones para la piedra.","Tres para el cielo.","Tres para el animal quieto de tu propio cuerpo, descansando.","Ahora deja descansar la historia y quédate con las sensaciones.","Inhala la frescura de este lugar.","Exhala hacia su calidez y tranquilidad.","Inhalar.","Exhalar.","De nuevo. Inhala suavemente.","Exhalación más larga.","Siente el cuerpo sostenido por el suelo de este mundo imaginado.","Inhalar.","Exhalar.","Si los pensamientos divagan, regrese al calor de la piel.","O para enfriar el aire en la nariz.","Inhalar.","Exhalar.","Inhalar.","Exhalar.","Permanecer. Ablandar. Continuar.","Inhalar.","Exhalar.","Un ciclo más fácil.","Inhalar.","Exhalar.","Permanece en este sentimiento durante unas cuantas respiraciones más.","Calor. Blandura. Suficiente.","Puedes regresar a este lugar cuando lo necesites.","Vive en tu atención, no sólo en tu imaginación.","Comience a profundizar la respiración.","Vuelve a sentir la habitación que te rodea.","Mueve los dedos. Suaviza los dedos de los pies.","Cuando estés listo, abre los ojos.","Respira tranquilamente una vez más.","Lleva esta calma a lo que venga después."]},"bamboo-garden-10":{"title":"Jardín de Bambú","summary":"Paseo por el jardín después de la lluvia, de frescor fresco y suave sol que regresa.","script":["Bienvenido.","Encuentra una postura que no te pida nada.","Siéntate o acuéstate con el apoyo que necesites.","Deja que tus manos descansen abiertas o suaves.","Deje que sus ojos se cierren o mantenga una mirada suave.","Siente los lugares donde tu cuerpo se encuentra con el suelo.","Los talones, los isquiones, la parte posterior de la cabeza o la longitud de la columna.","No hay nada que retrasar ahora.","Respire lentamente por la nariz.","Siente el frescor del aire llegando.","Y exhale un poco más.","Siente el calor de la exhalación al irse.","De nuevo. Inhala suavemente.","Exhala sin prisas.","Deja que los hombros caigan una fracción.","Deja que la mandíbula se afloje.","Deja que la barriga esté suave.","Quédate con tres respiraciones tranquilas, tal como están.","Inhalar. Llegar.","Exhalar. Asentarse.","Si la mente divaga, obsérvalo con amabilidad y regresa a esta respiración.","Imagínese un jardín de bambú después de la lluvia.","La piedra es oscura y limpia. Las hojas brillan.","La frescura fresca llena el aire como una suave campana.","Un claro entre las nubes deja pasar el sol.","Sienta un calor suave y repentino en la frente y los pómulos.","El vapor se eleva débilmente desde el camino y la tierra exhala.","Se pisan unos escalones cubiertos de musgo.","Cada piedra es fresca y segura bajo los pies.","El bambú cruje y susurra con una ligera brisa.","El sonido es verde. El sonido es tranquilo.","Huele hojas mojadas, piedra y un leve dulzor de plantas de té cercanas.","Haga una pausa junto a un pequeño estanque.","Los koi se mueven como pensamientos lentos bajo la superficie.","Las motas de sol calientan tus muñecas mientras las apoyas en la barandilla.","Una brisa refresca la humedad de tus sienes.","Frescura adentro. Suavidad afuera.","Siga un camino cubierto de madera desgastada.","Las tablas son frescas en la sombra, más cálidas cuando cae la luz.","Te sientas en un banco frente a grava rastrillada y una piedra perfecta.","No es necesario reorganizar nada.","Siente cómo la geometría tranquila tranquiliza tu mente.","El calor regresa a medida que las nubes se disipan: una mano amable sobre tus hombros.","Luego vuelve a dar sombra, fresca y relajante.","Bebe té imaginario. Pruebe la calidez. Siente el calor de la taza en tus palmas.","Fuera del jardín, la vida continúa. En el interior, el tiempo se afloja.","Camine una vez más bajo el bambú.","Deje que los altos tallos muevan su respiración al mismo ritmo suave.","El fresco goteo de una hoja llega a tu muñeca: una pequeña y fresca sorpresa.","Luego volver al sol, calentar en el mismo lugar hasta que se seque.","Perteneces a esta paz mientras permanezcas.","Y un hilo te acompañará cuando te vayas.","Siéntate una vez más. Manos abiertas sobre las rodillas.","Calidez allí donde la luz toca. Frescor a la sombra del bambú.","Inhala el frescor después de la lluvia.","Exhala en el silencio rastrillado de piedra y grava.","No queda nada afilado. Sólo bordes suaves y suficiente aire.","Regrese al estanque para una pausa final.","Las ondas de una gota caída se amplían y desaparecen.","Las motas de sol bailan y luego se quedan quietas.","Calor en el pómulo. Recuerdo de niebla fresca en nariz.","Inclínate levemente hacia el jardín, un pequeño asentimiento hacia adentro.","Camine por los escalones una vez más, más lento que antes.","Musgo fresco entre piedras. Madera cálida de la barandilla del puente.","El bambú habla en el lenguaje de las hojas en lo alto.","Ya entiendes bastante: quédate, ablanda, continúa.","En el umbral, sienta ambos mundos: la paz del jardín y el día normal.","Puedes trenzarlos.","Inhala frescura para la trenza.","Exhala calidez en las manos, listo para afrontar lo que viene.","El jardín permanece, mires o no.","Ahora deja descansar la historia y quédate con las sensaciones.","Inhala la frescura de este lugar.","Exhala hacia su calidez y tranquilidad.","Inhalar.","Exhalar.","De nuevo. Inhala suavemente.","Exhalación más larga.","Siente el cuerpo sostenido por el suelo de este mundo imaginado.","Inhalar.","Exhalar.","Si los pensamientos divagan, regrese al calor de la piel.","O para enfriar el aire en la nariz.","Inhalar.","Exhalar.","Inhalar.","Exhalar.","Permanecer. Ablandar. Continuar.","Inhalar.","Exhalar.","Un ciclo más fácil.","Inhalar.","Exhalar.","Permanece en este sentimiento durante unas cuantas respiraciones más.","Calor. Blandura. Suficiente.","Puedes regresar a este lugar cuando lo necesites.","Vive en tu atención, no sólo en tu imaginación.","Comience a profundizar la respiración.","Vuelve a sentir la habitación que te rodea.","Mueve los dedos. Suaviza los dedos de los pies.","Cuando estés listo, abre los ojos.","Respira tranquilamente una vez más.","Lleva esta calma a lo que venga después."]}}`),i={"soft-drone":{name:`Drone suave`},"warm-pad":{name:`Almohadilla caliente`},"ocean-hum":{name:`Zumbido del océano`},"mixkit-109-deep-meditation":{name:`Meditación profunda`},"mixkit-324-smooth-meditation":{name:`Meditación suave`},"mixkit-365-relaxation-meditation":{name:`Meditación de relajación`},"mixkit-18-singing-bowl-meditation":{name:`Meditación en cuenco tibetano`},"mixkit-21-indian-meditations":{name:`Meditaciones indias`},"mixkit-345-nature-meditation":{name:`Meditación de la naturaleza`},"mixkit-442-nature-yoga":{name:`Yoga en la naturaleza`},"mixkit-139-spirit-in-the-woods":{name:`Espíritu en el bosque`},"mixkit-148-forest-mist-whispers":{name:`Susurros de niebla del bosque`},"mixkit-138-forest-treasure":{name:`Tesoro del bosque`},"mixkit-127-valley-sunset":{name:`Atardecer en el valle`},"mixkit-444-yoga-song":{name:`Canción de yoga`},"mixkit-325-yoga-tune":{name:`Melodía de yoga`},"mixkit-27-serene-moments":{name:`Momentos serenos`},"mixkit-669-harp-relax":{name:`arpa relajarse`},"mixkit-168-staring-at-the-night-sky":{name:`Mirando al cielo nocturno`},"mixkit-419-pilates-and-yoga":{name:`pilates y yoga`}},a={"foundations-to-peak":{name:`Fundamentos → Guerrero pico`,description:`Aumente la capacidad durante cuatro semanas: suelo suave, calor del sol A, flujo constante y luego una cima guerrera más larga. Toque el "uso" de cada semana cuando esté listo para avanzar.`,weeks:[{label:`Semana 1 · Llegar`},{label:`Semana 2 · Calor`},{label:`Semana 3 · Stand`},{label:`Semana 4 · Pico`}]},"calm-month":{name:`Mes tranquilo`,description:`Un mes más tranquilo para el sistema nervioso: movilidad matutina, yin para las caderas y la columna, y luego una tarde reparadora. Utilice una semana a la vez; quédese más tiempo en una semana si lo necesita.`,weeks:[{label:`Semana 1 · Movilidad`},{label:`Semana 2 · Caderas Yin`},{label:`Semana 3 · Columna Yin`},{label:`Semana 4 · Restaurar`}]}},o={poses:e,routines:t,learn:n,meditations:r,music:i,progressions:a};export{o as default,n as learn,r as meditations,i as music,e as poses,a as progressions,t as routines};